DROP FUNCTION IF EXISTS `Account_GetParentName`;
DELIMITER //
CREATE FUNCTION `Account_GetParentName`(`p_AccID` BIGINT) RETURNS VARCHAR(80) DETERMINISTIC
BEGIN
DECLARE v_AccType VARCHAR(80);
    SELECT CASE          WHEN EXISTS (SELECT 1 FROM CustomersTb c WHERE c.AccID = a.AccID) THEN 'عميل'         WHEN EXISTS (SELECT 1 FROM CoBranch cb WHERE cb.CurrentAccID = a.AccID AND cb.BranchType=3) THEN 'وكيل'         WHEN EXISTS (SELECT 1 FROM CoBranch cb WHERE cb.CurrentAccID = a.AccID AND cb.BranchType=1) THEN 'فرع'         WHEN EXISTS (SELECT 1 FROM AddPartnerTb apt WHERE apt.CurrentAcc = a.AccID ) THEN 'شريك'         WHEN EXISTS (SELECT 1 FROM EmployeeTb et WHERE et.AccID = a.AccID ) THEN 'موظف'         WHEN a.AccParent LIKE '2010110%' THEN 'شريك مشروع'         WHEN a.AccParent LIKE '2010140%' THEN 'مورد'         WHEN a.AccParent LIKE '2030201%' THEN 'مندوب توصيل'         WHEN a.AccParent LIKE '2010120%' THEN 'مقاول'         ELSE 'حساب'      END INTO v_AccType FROM AccountsTb a
    WHERE a.AccID=p_AccID;
    IF v_AccType IS NULL
       THEN
SET v_AccType = 'حساب';
      END IF;
    RETURN v_AccType;
  END //
DELIMITER ;

