DROP FUNCTION IF EXISTS `AccSafeActivityTb_TOTETDATE`;
DELIMITER //
CREATE FUNCTION `AccSafeActivityTb_TOTETDATE`(`p_ACCID` INT, `p_ACCDAATE` DATE, `p_acctupe` INT, `p_CurrencyFrom` INT) RETURNS DECIMAL(13,3) DETERMINISTIC
BEGIN
DECLARE v_AccSafeActivity DECIMAL(13, 3);
DECLARE v_AccCranse INT;
		SELECT CMT.IsDefault INTO v_AccCranse FROM
				CurrencyMainTb AS CMT
		WHERE
				CMT.ID = p_CurrencyFrom
 ORDER BY CMT.ID DESC LIMIT 1;

		IF v_AccCranse = 1
			 THEN
				SELECT CASE 												  WHEN p_acctupe = 0 													  THEN 													  IFNULL(SUM(A.Debit), 0) - IFNULL(SUM(Credit), 0) 												  WHEN p_acctupe = 1 													  THEN 													  IFNULL(SUM(A.Credit), 0) - IFNULL(SUM(Debit), 0) 										  END INTO v_AccSafeActivity FROM
						ExSyAccounts_AccSafeActivityTb AS A
				WHERE
						A.InsertDate < p_ACCDAATE
						AND A.IsActive = 1
						AND A.AccIDFrom = p_ACCID;
			END IF;

		IF v_AccCranse = 0
			 THEN
				SELECT CASE 												  WHEN p_acctupe = 0 													  THEN 													  IFNULL(SUM(Credit), 0) - IFNULL(SUM(A.Debit), 0)  												  WHEN p_acctupe = 1 													  THEN 													  IFNULL(SUM(A.Credit), 0) - IFNULL(SUM(Debit), 0) 										  END INTO v_AccSafeActivity FROM
						ExSyAccountsCurrency_AccSafeActivityTb AS A
				WHERE
						A.InsertDate < p_ACCDAATE
						AND A.IsActive = 1
						AND A.AccIDFrom = p_ACCID;
			END IF;

		RETURN IFNULL(v_AccSafeActivity, 0);
	END //
DELIMITER ;

