DROP FUNCTION IF EXISTS `BBranchMOVEMENT_GetNetTotal`;
DELIMITER //
CREATE FUNCTION `BBranchMOVEMENT_GetNetTotal`(`p_AccName` BIGINT, `p_BranchID` INT, `p_ID` BIGINT, `p_CurrencyID` INT) RETURNS DECIMAL(15,3) DETERMINISTIC
BEGIN
DECLARE v_AccCreditVal DECIMAL(15, 3);
DECLARE v_AccdebitVal DECIMAL(15, 3);
DECLARE v_FinalAccVal DECIMAL(15, 3);
DECLARE v_NetVal DECIMAL(15, 3);
DECLARE v_AccVal DECIMAL(15, 3);
DECLARE v_MaxID BIGINT;
DECLARE v_CurrenDebit DECIMAL(15, 3);
DECLARE v_CurrenCredit DECIMAL(15, 3);
DECLARE v_IsDefault INT;
	SELECT IsDefault INTO v_IsDefault FROM CurrencyMainTb AS CMT
	where cmt.ID=p_CurrencyID
 ORDER BY CMT.ID DESC LIMIT 1;
	IF v_IsDefault=1
	 THEN
		SELECT IFNULL( SUM( a.Credit ), 0.000 ) INTO v_AccCreditVal FROM ExSyAccounts_AccSafeActivityTb AS a
		WHERE a.IsActive=1
			  AND a.AccIDFrom=p_AccName
			  AND a.AccBranchID=p_BranchID
			  AND a.ID<p_ID;
		SELECT IFNULL( SUM( a.Debit ), 0.000 ) INTO v_AccdebitVal FROM ExSyAccounts_AccSafeActivityTb AS a
		WHERE a.IsActive=1
			  AND a.AccIDFrom=p_AccName
			  AND a.AccBranchID=p_BranchID
			  AND a.ID<p_ID;
		SELECT a.Credit INTO v_CurrenCredit FROM ExSyAccounts_AccSafeActivityTb AS a
		WHERE a.IsActive=1
			  AND a.AccIDFrom=p_AccName
			  AND a.AccBranchID=p_BranchID
			  AND a.ID=p_ID;
		SELECT a.Debit INTO v_CurrenDebit FROM ExSyAccounts_AccSafeActivityTb AS a
		WHERE a.IsActive=1
			  AND a.AccIDFrom=p_AccName
			  AND a.AccBranchID=p_BranchID
			  AND a.ID=p_ID;
SET v_AccVal=v_AccdebitVal-v_AccCreditVal;
		IF v_CurrenCredit>v_CurrenDebit
		 THEN
SET v_NetVal=v_AccVal+v_CurrenCredit;
		END IF;

		IF v_CurrenCredit<v_CurrenDebit
		 THEN
SET v_NetVal=v_AccVal-v_CurrenDebit;
		END IF;

	END IF;

	IF v_IsDefault=0
	 THEN
		SELECT IFNULL( SUM( a.Credit ), 0.000 ) INTO v_AccdebitVal FROM ExSyAccountsCurrency_AccSafeActivityTb AS a
		WHERE a.IsActive=1
			  AND a.AccIDFrom=p_AccName
			  AND a.AccBranchID=p_BranchID
			  AND a.ID<p_ID
			  AND a.CurrencyID=p_CurrencyID;

		SELECT IFNULL( SUM( a.Debit ), 0.000 ) INTO v_AccCreditVal FROM ExSyAccountsCurrency_AccSafeActivityTb AS a
		WHERE a.IsActive=1
			  AND a.AccIDFrom=p_AccName
			  AND a.AccBranchID=p_BranchID
			  AND a.ID<p_ID
			  AND a.CurrencyID=p_CurrencyID;
		SELECT a.Credit INTO v_CurrenDebit FROM ExSyAccountsCurrency_AccSafeActivityTb AS a
		WHERE a.IsActive=1
			  AND a.AccIDFrom=p_AccName
			  AND a.AccBranchID=p_BranchID
			  AND a.ID=p_ID
			  AND a.CurrencyID=p_CurrencyID;
		SELECT a.Debit INTO v_CurrenCredit FROM ExSyAccountsCurrency_AccSafeActivityTb AS a
		WHERE a.IsActive=1
			  AND a.AccIDFrom=p_AccName
			  AND a.AccBranchID=p_BranchID
			  AND a.ID=p_ID
			  AND a.CurrencyID=p_CurrencyID;
SET v_AccVal=v_AccCreditVal-v_AccdebitVal;
		IF v_CurrenCredit>v_CurrenDebit
		 THEN
SET v_NetVal=v_AccVal+v_CurrenCredit;
		END IF;

		IF v_CurrenCredit<v_CurrenDebit
		 THEN
SET v_NetVal=v_AccVal-v_CurrenDebit;
		END IF;

	END IF;


	RETURN v_NetVal;
END //
DELIMITER ;

DROP FUNCTION IF EXISTS `Branch_GetAccVal`;
DELIMITER //
CREATE FUNCTION `Branch_GetAccVal`(`p_BranchID` INT) RETURNS DECIMAL(18,3) DETERMINISTIC
BEGIN
DECLARE v_BranchOutcomeTotal DECIMAL(15, 3);
DECLARE v_BranchBalance DECIMAL(15, 3);
DECLARE v_AccVal DECIMAL(15, 3);


SELECT IFNULL(  SUM(d.Debit)-SUM(d.Credit), 0) INTO v_BranchOutcomeTotal FROM
        `AccountsTb` AS A
    INNER JOIN
      ExSyAccounts_AccSafeActivityTb AS d
        ON d.AccIDFrom = a.AccID
WHERE
        (       a.AccParent = '2010601'
                OR a.AccParent = '2010602'
                OR a.AccParent = '2010603'
                OR a.AccParent = '2010604')
        AND d.IsActive = 1
        AND d.AccBranchID = p_BranchID;

        	 SELECT IFNULL(SUM(d.Debit)-SUM(d.Credit), 0) INTO v_BranchBalance FROM
        `AccountsTb` AS A
    INNER JOIN
      ExSyAccounts_AccSafeActivityTb AS d
        ON d.AccIDFrom = a.AccID
WHERE
        (      A.AccParent = '2010201')
        AND d.IsActive = 1
        AND d.AccBranchID = p_BranchID;
SET v_AccVal=v_BranchOutcomeTotal+v_BranchBalance;
    IF v_AccVal IS NULL
       THEN
SET v_AccVal = 0.000;
      END IF;
    RETURN v_AccVal;
  END //
DELIMITER ;

DROP FUNCTION IF EXISTS `Branch_GetInteralBene`;
DELIMITER //
CREATE FUNCTION `Branch_GetInteralBene`(`p_RBranchID` INT, `p_DBranchID` INT, `p_InputVal` DECIMAL(12,3)) RETURNS DECIMAL(15,3) DETERMINISTIC
BEGIN
DECLARE v_RBrType INT;
DECLARE v_DBrType INT;
DECLARE v_CulRes DECIMAL(12 ,3);
DECLARE v_RestShare DECIMAL(12 ,3);
DECLARE v_BrRt DECIMAL(12 ,3);
DECLARE v_RBShare DECIMAL(12 ,3);
DECLARE v_DBShare DECIMAL(12 ,3);
DECLARE v_DbrRt DECIMAL(12 ,3);
DECLARE v_AgentRestVal DECIMAL(12 ,3);
DECLARE v_BrVal DECIMAL(12 ,3);
DECLARE v_MainBr INT;
	SELECT ID INTO v_MainBr FROM   CoBranch
	WHERE  IsMain = 1;

	SET v_RBrType = ( SELECT BranchType FROM   CoBranch WHERE  ID = p_RBranchID );
	SET v_DBrType = ( SELECT BranchType FROM   CoBranch WHERE  ID = p_DBranchID );
		 IF p_RBranchID=v_MainBr
	     THEN
	        SELECT MainBranchBenefit INTO v_DbrRt FROM   CoBranch
	        WHERE  id = p_DBranchID;
SET v_DBShare = p_InputVal*v_DbrRt/100;
SET v_BrVal = p_InputVal- v_DBShare;
SET v_RestShare = 0.000;
	    END IF;
		 IF p_DBranchID=v_MainBr
	         THEN
	            SELECT MainBranchBenefit INTO v_BrRt FROM   CoBranch
	            WHERE  id = p_RBranchID;
SET v_RBShare = p_InputVal*v_BrRt/100;
SET v_BrVal = p_InputVal- v_RBShare;
SET v_RestShare = 0.000;
	        END IF;
			IF p_DBranchID<>v_MainBr and p_RBranchID <> v_MainBr and v_DBrType=1 AND v_RBrType=1
	     THEN


	            SELECT BranchRate INTO v_BrRt FROM   CoBranch
	            WHERE  id = p_RBranchID;

	            SELECT BranchRate INTO v_DbrRt FROM   CoBranch
	            WHERE  id = p_DBranchID;
SET v_RBShare = p_InputVal*v_BrRt/100;
SET v_DBShare = p_InputVal*v_DbrRt/100;
SET v_CulRes = v_RBShare+v_DBShare;
	            IF v_CulRes<>0
	             THEN
SET v_RestShare = p_InputVal- v_CulRes;
	            END IF;

	END IF;

         RETURN IFNULL(v_BrVal, 0.000);
     END //
DELIMITER ;

DROP FUNCTION IF EXISTS `Branch_GetNetVal`;
DELIMITER //
CREATE FUNCTION `Branch_GetNetVal`(`p_BranchID` BIGINT, `p_DebitOrCredit` TINYINT UNSIGNED) RETURNS DECIMAL(18,3) DETERMINISTIC
BEGIN
DECLARE v_BranchOutComeVal DECIMAL(18, 3);
DECLARE v_BranchInComeVal DECIMAL(18, 3);
DECLARE v_BranchVal DECIMAL(18, 3);
DECLARE v_AccVal DECIMAL(18, 3);


    SELECT IFNULL(SUM(Credit) - SUM(Debit), 0) INTO v_BranchOutComeVal FROM
            `AccountsTb` AS A
        INNER JOIN
          ExSyAccounts_AccSafeActivityTb AS b
            ON b.AccIDFrom = a.AccID
    WHERE
            (       a.AccParent = '2010601'
                    OR a.AccParent = '2010602'
                    OR a.AccParent = '2010603'
                    OR a.AccParent = '2010604')
            AND b.IsActive = 1
            AND b.AccBranchID = p_BranchID;


    SELECT IFNULL(SUM(Credit) - SUM(Debit), 0) INTO v_BranchVal FROM
            `AccountsTb` AS A
        INNER JOIN
          ExSyAccounts_AccSafeActivityTb AS d
            ON d.AccIDFrom = a.AccID
    WHERE
            A.AccParent = '2010201'
            AND d.AccBranchID = p_BranchID;


    SELECT IFNULL(SUM(Debit) - SUM(Credit), 0) INTO v_BranchInComeVal FROM
            `AccountsTb` AS A
        INNER JOIN
          ExSyAccounts_AccSafeActivityTb AS b
            ON b.AccIDFrom = a.AccID
    WHERE
            (       a.AccParent = '1010601'
                    OR a.AccParent = '1010602'
                    OR a.AccParent = '1010603'
                    OR a.AccParent = '1010604')
            AND b.IsActive = 1
            AND b.AccBranchID = p_BranchID;

    IF p_DebitOrCredit = 0
       THEN
SET v_AccVal = v_BranchInComeVal + CASE                                                     WHEN v_BranchVal > 0                                                       THEN                                                       0                                                     ELSE                                                     (v_BranchVal * -1)                                             END;
      END IF;

    IF p_DebitOrCredit = 1
       THEN
SET v_AccVal = v_BranchOutComeVal + CASE                                                      WHEN v_BranchVal > 0                                                        THEN                                                        v_BranchVal                                                      ELSE                                                      0                                              END;
      END IF;

    IF p_DebitOrCredit = 2
       THEN
        SET v_AccVal = (v_BranchOutComeVal - v_BranchInComeVal) + IFNULL(v_BranchVal, 0);
      END IF;

    IF v_AccVal IS NULL
       THEN
SET v_AccVal = 0.000;
      END IF;
    RETURN v_AccVal;
  END //
DELIMITER ;

DROP FUNCTION IF EXISTS `BranchAllSafes_GetAccVal`;
DELIMITER //
CREATE FUNCTION `BranchAllSafes_GetAccVal`(`p_BranchID` INT, `p_D1` DATE, `p_D2` DATE) RETURNS DECIMAL(15,3) DETERMINISTIC
BEGIN
DECLARE v_AccCreditVal decimal(15,3);
DECLARE v_AccdebitVal decimal(15,3);
DECLARE v_AccVal decimal(15,3);




	SELECT sum(a.Debit)-sum(a.credit) INTO v_AccVal FROM ExSyAccounts_AccSafeActivityTb AS a LEFT OUTER JOIN AccountsTb AS b ON a.AccIDFrom=b.AccID
	WHERE a.AccBranchID	=p_BranchID AND a.InsertDate>=p_D1 AND a.InsertDate<=p_D2 AND  LEFT(b.AccParent,3)=10101;





	if v_AccVal= 0.000  THEN 	SET v_AccVal = 0.000;END IF;

	RETURN IFNULL((v_AccVal), 0.000);
END //
DELIMITER ;

DROP FUNCTION IF EXISTS `BranchAllSafes_GetBenefits`;
DELIMITER //
CREATE FUNCTION `BranchAllSafes_GetBenefits`(`p_BranchID` INT, `p_D1` DATE, `p_D2` DATE) RETURNS DECIMAL(15,3) DETERMINISTIC
BEGIN
DECLARE v_AccVal DECIMAL(15, 3);
         SELECT CASE WHEN SUM(a.Debit) - SUM(a.credit) > SUM(a.Credit) - SUM(a.Debit) then SUM(a.Debit) - SUM(a.credit)  		 WHEN SUM(a.Debit) - SUM(a.credit) < SUM(a.Credit) - SUM(a.Debit) THEN SUM(a.Credit) - SUM(a.Debit) END INTO v_AccVal FROM ExSyAccounts_AccSafeActivityTb AS a
              LEFT OUTER JOIN AccountsTb AS b ON a.AccIDFrom = b.AccID
         WHERE b.BranchID = p_BranchID
               AND a.InsertDate >= p_D1
               AND a.InsertDate <= p_D2
               AND (b.AccParent = 401
                    OR b.AccParent = 401
                    OR b.AccParent = 401
                    OR b.AccParent = 401
                    OR b.AccCode = 401);
					IF v_AccVal	= 0.000  THEN 	SET v_AccVal = 0.000;END IF;
         RETURN IFNULL(v_AccVal,0.000);
     END //
DELIMITER ;

