DROP FUNCTION IF EXISTS `CUSTMOVEMENTSTATEMENT_GETCREDITTOTAL`;
DELIMITER //
CREATE FUNCTION `CUSTMOVEMENTSTATEMENT_GETCREDITTOTAL`(`p_AccID` BIGINT, `p_D1` DATE, `p_D2` DATE) RETURNS DECIMAL(15,3) DETERMINISTIC
BEGIN
DECLARE v_AccCreditVal DECIMAL(15, 3);
DECLARE v_AccdebitVal DECIMAL(15, 3);
DECLARE v_AccVal DECIMAL(15, 3);
         SELECT IFNULL(SUM(a.Credit), 0.000) INTO v_AccCreditVal FROM ExSyAccounts_AccSafeActivityTb AS a
              LEFT JOIN CurrencyTb AS b ON a.CurrencyID = b.ID
         WHERE a.AccIDFrom = p_AccID
               AND a.IsActive = 1
               AND A.InsertDate BETWEEN CAST(p_D1 AS DATE) AND CAST(p_D2 AS DATE);
         RETURN v_AccCreditVal;
     END //
DELIMITER ;

