DROP FUNCTION IF EXISTS `CustTB_GetIsHaideenAcc`;
DELIMITER //
CREATE FUNCTION `CustTB_GetIsHaideenAcc`(`p_AccName` BIGINT, `p_UserID` INT) RETURNS TINYINT(1) DETERMINISTIC
BEGIN
DECLARE v_IsHaideen bit;
DECLARE v_CanShowHACC BIT;

SELECT IFNULL(HiddenAccount,0) INTO v_IsHaideen FROM AccountsTb a
INNER JOIN CustomersTb b ON a.AccID=b.AccID  WHERE a.AccID=p_AccName;
SELECT tu.CanShowHACC INTO v_CanShowHACC FROM TB_Users tu WHERE tu.USID=p_UserID
 ORDER BY tu.USID DESC LIMIT 1;

IF v_IsHaideen=1 AND v_CanShowHACC=1
 THEN
SET v_IsHaideen=0;
END IF;




	RETURN IFNULL(v_IsHaideen,0);
END //
DELIMITER ;

DROP FUNCTION IF EXISTS `DailyCloseTb_GetSumTotalCredit`;
DELIMITER //
CREATE FUNCTION `DailyCloseTb_GetSumTotalCredit`(`p_BranchID` INT, `p_CurrencyID` INT, `p_InsertDateFrom` DATE, `p_InsertDateTo` DATE) RETURNS DECIMAL(15,3) DETERMINISTIC
BEGIN
DECLARE v_NetTtoal DECIMAL(15, 3);
		BEGIN
			SELECT IFNULL(SUM(a.OverallCredit), 0) INTO v_NetTtoal FROM
					DailyCloseTb AS a

			WHERE
					a.BranchID = p_BranchID
					AND a.CurrnecyID = p_CurrencyID
					AND a.BranchID = p_BranchID
					AND a.InsertDate >= p_InsertDateFrom
					AND a.InsertDate <= p_InsertDateTo
					AND a.IsActive = 1;
		END;
		RETURN v_NetTtoal;
	END //
DELIMITER ;

DROP FUNCTION IF EXISTS `DailyCloseTb_GetSumTotalDebit`;
DELIMITER //
CREATE FUNCTION `DailyCloseTb_GetSumTotalDebit`(`p_BranchID` INT, `p_CurrencyID` INT, `p_InsertDateFrom` DATE, `p_InsertDateTo` DATE) RETURNS DECIMAL(15,3) DETERMINISTIC
BEGIN
DECLARE v_NetTtoal DECIMAL(15, 3);
		BEGIN
			SELECT IFNULL(SUM(a.OverallDebit), 0) INTO v_NetTtoal FROM
					DailyCloseTb AS a

			WHERE
					a.BranchID = p_BranchID
					AND (   a.CurrnecyID = p_CurrencyID
							OR a.CurrnecyID = 13)
					AND a.BranchID = p_BranchID
					AND a.InsertDate >= p_InsertDateFrom
					AND a.InsertDate <= p_InsertDateTo
					AND a.IsActive = 1;
		END;
		RETURN v_NetTtoal;
	END //
DELIMITER ;

