DROP FUNCTION IF EXISTS `EMP_GetADVPMNTTtoals`;
DELIMITER //
CREATE FUNCTION `EMP_GetADVPMNTTtoals`(`p_EMPID` INT) RETURNS DECIMAL(15,3) DETERMINISTIC
BEGIN
DECLARE v_AccCreditVal decimal(15,3);

	SELECT IFNULL(sum(a.ValPerMonth),0.000) INTO v_AccCreditVal FROM AdvancePaymentTb  as a LEFT JOIN  EmployeeTb as b on a.EMPID  = b.ID WHERE b.ID=p_EMPID AND a.IsActive=1 AND b.ISACTIVE=1 AND a.IsOpened=1;


	RETURN IFNULL( v_AccCreditVal,0.000);
END //
DELIMITER ;

DROP FUNCTION IF EXISTS `EMP_GetADVPMNTTtoalsIndivdual`;
DELIMITER //
CREATE FUNCTION `EMP_GetADVPMNTTtoalsIndivdual`(`p_EMPID` INT) RETURNS DECIMAL(15,3) DETERMINISTIC
BEGIN
DECLARE v_AccCreditVal decimal(15,3);

	SELECT IFNULL(a.OverAllVal,0.000) - IFNULL(sum(a.PaidVal),0.000) INTO v_AccCreditVal FROM AdvancePaymentTb  as a LEFT JOIN  EmployeeTb as b on a.EMPID  = b.ID WHERE b.ID=p_EMPID AND a.IsActive=1 AND b.ISACTIVE=1 AND a.IsOpened=1 GROUP by a.OverAllVal
 ORDER BY a.OverAllVal DESC LIMIT 1;


	RETURN IFNULL( v_AccCreditVal,0.000);
END //
DELIMITER ;

