DECLARE v_AccCreditVal decimal(15,3);

	SELECT IFNULL( sum(a.INCVAL),0.000) INTO v_AccCreditVal FROM IncreaseValTb as a LEFT JOIN  EmployeeTb as b on a.EMPID  = b.ID WHERE b.ID=p_EMPID AND a.IsActive=1 AND a.IsOpened	=1 AND a.IsConstant=1;


	RETURN IFNULL( v_AccCreditVal,0.000);
END //
