DELIMITER //
CREATE FUNCTION `EMP_GetDiscTtoals`(`p_EMPID` INT) RETURNS DECIMAL(15,3) DETERMINISTIC
BEGIN
DECLARE v_AccCreditVal decimal(15,3);

	SELECT IFNULL( sum(a.DISVAL),0.000) INTO v_AccCreditVal FROM DiscountValTb as a LEFT JOIN  EmployeeTb as b on a.EMPID  = b.ID WHERE b.ID=p_EMPID AND a.IsActive=1 AND a.IsOpened	=1;


	RETURN IFNULL( v_AccCreditVal,0.000);
END //
DELIMITER ;

DROP FUNCTION IF EXISTS `EMP_GetLeaveDiscountTotal`;
DELIMITER //
CREATE FUNCTION `EMP_GetLeaveDiscountTotal`(`p_EMPID` INT) RETURNS DECIMAL(15,3) DETERMINISTIC
BEGIN
DECLARE v_TotalDiscount DECIMAL(15, 3) DEFAULT 0.000;

    SELECT IFNULL(SUM(L.DiscountVal), 0.000) INTO v_TotalDiscount FROM
            LeaveTB AS L
        INNER JOIN
          EmployeeTb AS E
            ON L.EMPID = E.ID
    WHERE
            L.EMPID = p_EMPID
            AND L.IsActive = 1
            AND E.ISACTIVE = 1
            AND (   L.LeaveType <> 0
                    OR L.IsAbsence = 1)
            AND L.EndLeave = 1
            AND L.IsCalculated = 0
            AND IsAccepted = 1;
    RETURN v_TotalDiscount;
  END //
DELIMITER ;

DROP FUNCTION IF EXISTS `EMP_GetNettoals`;
DELIMITER //
CREATE FUNCTION `EMP_GetNettoals`(`p_EMPID` INT) RETURNS DECIMAL(15,3) DETERMINISTIC
BEGIN
DECLARE v_AccCreditVal DECIMAL(15 , 3);
DECLARE v_TempVal DECIMAL(15 , 3);
DECLARE v_ConsatanceVal DECIMAL(15 , 3);
DECLARE v_FinalTotal DECIMAL(15 , 3);


    SELECT b.SalaryVal + `EMP_GetTempIncreaseToals`(p_EMPID) + `EMP_GetConstanceIncreaseToals`(p_EMPID) - `EMP_GetDiscTtoals`(p_EMPID) - `EMP_GetADVPMNTTtoals`(p_EMPID) - EMP_GetLeaveDiscountTotal(p_EMPID) INTO v_AccCreditVal FROM EmployeeTb AS b
    WHERE b.ID = p_EMPID
          AND
          b.IsActive = 1;
    RETURN IFNULL(v_AccCreditVal , 0.000);
  END //
DELIMITER ;

