DROP FUNCTION IF EXISTS `EMPMOVEMENT_GetNetTotal`;
DELIMITER //
CREATE FUNCTION `EMPMOVEMENT_GetNetTotal`(`p_AccName` BIGINT, `p_BranchID` INT, `p_ID` BIGINT, `p_CurrencyTo` INT, `p_Type` TINYINT UNSIGNED) RETURNS DECIMAL(15,3) DETERMINISTIC
BEGIN
DECLARE v_AccCreditVal DECIMAL(15, 3);
DECLARE v_AccdebitVal DECIMAL(15, 3);
DECLARE v_FinalAccVal DECIMAL(15, 3);
DECLARE v_NetVal DECIMAL(15, 3);
DECLARE v_AccVal DECIMAL(15, 3);
DECLARE v_MaxID BIGINT;
DECLARE v_CurrenDebit DECIMAL(15, 3);
DECLARE v_CurrenCredit DECIMAL(15, 3);
DECLARE v_CurrencyID BIT;
		SELECT IsDefault INTO v_CurrencyID FROM
				CurrencyMainTb AS CMT
		WHERE
				ID = p_CurrencyTo
 ORDER BY CMT.ID DESC LIMIT 1;



		IF v_CurrencyID = 1
			 THEN

			IF p_Type = 0
			 THEN
				SELECT IFNULL(SUM(a.Credit), 0.000) INTO v_AccCreditVal FROM
						ExSyAccounts_AccSafeActivityTb AS a
					LEFT JOIN
						AccountsTb AS b
							ON a.AccIDFrom = b.AccID
				WHERE
						a.IsActive = 1
						AND a.AccIDFrom = p_AccName
						AND a.AccBranchID = p_BranchID
						AND a.ID < p_ID
						AND (a.CurrencyID = p_CurrencyTo or a.CurrencyID =13);
				SELECT IFNULL(SUM(a.Debit), 0.000) INTO v_AccdebitVal FROM
						ExSyAccounts_AccSafeActivityTb AS a
					LEFT JOIN
						AccountsTb AS b
							ON a.AccIDFrom = b.AccID
				WHERE
						a.IsActive = 1
						AND a.AccIDFrom = p_AccName
						AND a.AccBranchID = p_BranchID
						AND a.ID < p_ID
						AND (a.CurrencyID = p_CurrencyTo or a.CurrencyID =13);
				SELECT a.Credit INTO v_CurrenCredit FROM
						ExSyAccounts_AccSafeActivityTb AS a
					LEFT JOIN
						AccountsTb AS b
							ON a.AccIDFrom = b.AccID
				WHERE
						a.IsActive = 1
						AND a.AccIDFrom = p_AccName
						AND a.AccBranchID = p_BranchID
						AND a.ID = p_ID
						AND (a.CurrencyID = p_CurrencyTo or a.CurrencyID =13);
				SELECT a.Debit INTO v_CurrenDebit FROM
						ExSyAccounts_AccSafeActivityTb AS a
					LEFT JOIN
						AccountsTb AS b
							ON a.AccIDFrom = b.AccID
				WHERE
						a.IsActive = 1
						AND a.AccIDFrom = p_AccName
						AND a.AccBranchID = p_BranchID
						AND a.ID = p_ID
						AND (a.CurrencyID = p_CurrencyTo or a.CurrencyID =13);
SET v_AccVal = v_AccCreditVal - v_AccdebitVal;
				IF v_CurrenCredit > v_CurrenDebit
					 THEN
SET v_NetVal = v_AccVal + v_CurrenCredit;
					END IF;

				IF v_CurrenCredit < v_CurrenDebit
					 THEN
SET v_NetVal = v_AccVal - v_CurrenDebit;
					END IF;

			END IF;
			END IF;


			IF p_Type = 1
			 THEN
				SELECT IFNULL(SUM(a.Credit), 0.000) INTO v_AccCreditVal FROM
						ExSyAccounts_AccSafeActivityTb AS a
					LEFT JOIN
						AccountsTb AS b
							ON a.AccIDFrom = b.AccID
				WHERE
						a.IsActive = 1
						AND a.AccIDFrom = p_AccName
						AND a.AccBranchID = p_BranchID
						AND a.ID < p_ID
						AND (a.CurrencyID = p_CurrencyTo or a.CurrencyID =13)
						AND a.IsBank=0;
				SELECT IFNULL(SUM(a.Debit), 0.000) INTO v_AccdebitVal FROM
						ExSyAccounts_AccSafeActivityTb AS a
					LEFT JOIN
						AccountsTb AS b
							ON a.AccIDFrom = b.AccID
				WHERE
						a.IsActive = 1
						AND a.AccIDFrom = p_AccName
						AND a.AccBranchID = p_BranchID
						AND a.ID < p_ID
						AND (a.CurrencyID = p_CurrencyTo or a.CurrencyID =13)
						AND a.IsBank=0;
				SELECT a.Credit INTO v_CurrenCredit FROM
						ExSyAccounts_AccSafeActivityTb AS a
					LEFT JOIN
						AccountsTb AS b
							ON a.AccIDFrom = b.AccID
				WHERE
						a.IsActive = 1
						AND a.AccIDFrom = p_AccName
						AND a.AccBranchID = p_BranchID
						AND a.ID = p_ID
						AND (a.CurrencyID = p_CurrencyTo or a.CurrencyID =13)
						AND a.IsBank=0;
				SELECT a.Debit INTO v_CurrenDebit FROM
						ExSyAccounts_AccSafeActivityTb AS a
					LEFT JOIN
						AccountsTb AS b
							ON a.AccIDFrom = b.AccID
				WHERE
						a.IsActive = 1
						AND a.AccIDFrom = p_AccName
						AND a.AccBranchID = p_BranchID
						AND a.ID = p_ID
						AND (a.CurrencyID = p_CurrencyTo or a.CurrencyID =13)
						AND a.IsBank=0;
SET v_AccVal = v_AccCreditVal - v_AccdebitVal;
				IF v_CurrenCredit > v_CurrenDebit
					 THEN
SET v_NetVal = v_AccVal + v_CurrenCredit;
					END IF;

				IF v_CurrenCredit < v_CurrenDebit
					 THEN
SET v_NetVal = v_AccVal - v_CurrenDebit;
					END IF;


			END IF;


						IF p_Type = 2
			 THEN
				SELECT IFNULL(SUM(a.Credit), 0.000) INTO v_AccCreditVal FROM
						ExSyAccounts_AccSafeActivityTb AS a
					LEFT JOIN
						AccountsTb AS b
							ON a.AccIDFrom = b.AccID
				WHERE
						a.IsActive = 1
						AND a.AccIDFrom = p_AccName
						AND a.AccBranchID = p_BranchID
						AND a.ID < p_ID
						AND (a.CurrencyID = p_CurrencyTo or a.CurrencyID =13)
						AND a.IsBank=1;
				SELECT IFNULL(SUM(a.Debit), 0.000) INTO v_AccdebitVal FROM
						ExSyAccounts_AccSafeActivityTb AS a
					LEFT JOIN
						AccountsTb AS b
							ON a.AccIDFrom = b.AccID
				WHERE
						a.IsActive = 1
						AND a.AccIDFrom = p_AccName
						AND a.AccBranchID = p_BranchID
						AND a.ID < p_ID
						AND (a.CurrencyID = p_CurrencyTo or a.CurrencyID =13)
						AND a.IsBank=1;
				SELECT a.Credit INTO v_CurrenCredit FROM
						ExSyAccounts_AccSafeActivityTb AS a
					LEFT JOIN
						AccountsTb AS b
							ON a.AccIDFrom = b.AccID
				WHERE
						a.IsActive = 1
						AND a.AccIDFrom = p_AccName
						AND a.AccBranchID = p_BranchID
						AND a.ID = p_ID
						AND (a.CurrencyID = p_CurrencyTo or a.CurrencyID =13)
						AND a.IsBank=1;
				SELECT a.Debit INTO v_CurrenDebit FROM
						ExSyAccounts_AccSafeActivityTb AS a
					LEFT JOIN
						AccountsTb AS b
							ON a.AccIDFrom = b.AccID
				WHERE
						a.IsActive = 1
						AND a.AccIDFrom = p_AccName
						AND a.AccBranchID = p_BranchID
						AND a.ID = p_ID
						AND (a.CurrencyID = p_CurrencyTo or a.CurrencyID =13)
						AND a.IsBank=1;
SET v_AccVal = v_AccCreditVal - v_AccdebitVal;
				IF v_CurrenCredit > v_CurrenDebit
					 THEN
SET v_NetVal = v_AccVal + v_CurrenCredit;
					END IF;

				IF v_CurrenCredit < v_CurrenDebit
					 THEN
SET v_NetVal = v_AccVal - v_CurrenDebit;
					END IF;


			END IF;

		IF v_CurrencyID = 0
			 THEN

				SELECT IFNULL(SUM(a.Debit), 0.000) INTO v_AccCreditVal FROM
						ExSyAccountsCurrency_AccSafeActivityTb AS a
					LEFT JOIN
						AccountsTb AS b
							ON a.AccIDFrom = b.AccID
				WHERE
						a.IsActive = 1
						AND a.AccIDFrom = p_AccName
						AND a.AccBranchID = p_BranchID
						AND a.ID < p_ID;
				SELECT IFNULL(SUM(a.Credit), 0.000) INTO v_AccdebitVal FROM
						ExSyAccountsCurrency_AccSafeActivityTb AS a
					LEFT JOIN
						AccountsTb AS b
							ON a.AccIDFrom = b.AccID
				WHERE
						a.IsActive = 1
						AND a.AccIDFrom = p_AccName
						AND a.AccBranchID = p_BranchID
						AND a.ID < p_ID
						AND a.CurrencyID = p_CurrencyTo;
				SELECT a.Debit INTO v_CurrenCredit FROM
						ExSyAccountsCurrency_AccSafeActivityTb AS a
					LEFT JOIN
						AccountsTb AS b
							ON a.AccIDFrom = b.AccID
				WHERE
						a.IsActive = 1
						AND a.AccIDFrom = p_AccName
						AND a.AccBranchID = p_BranchID
						AND a.ID = p_ID
						AND a.CurrencyID = p_CurrencyTo;
				SELECT a.Credit INTO v_CurrenDebit FROM
						ExSyAccountsCurrency_AccSafeActivityTb AS a
					LEFT JOIN
						AccountsTb AS b
							ON a.AccIDFrom = b.AccID
				WHERE
						a.IsActive = 1
						AND a.AccIDFrom = p_AccName
						AND a.AccBranchID = p_BranchID
						AND a.ID = p_ID
						AND a.CurrencyID = p_CurrencyTo;
SET v_AccVal = v_AccCreditVal - v_AccdebitVal;
				IF v_CurrenCredit > v_CurrenDebit
					 THEN
SET v_NetVal = v_AccVal + v_CurrenCredit;
					END IF;

				IF v_CurrenCredit < v_CurrenDebit
					 THEN
SET v_NetVal = v_AccVal - v_CurrenDebit;
					END IF;

			END IF;




		RETURN v_NetVal;
	END //
DELIMITER ;

