DROP FUNCTION IF EXISTS `EMPORCUST_GetAccVal`;
DELIMITER //
CREATE FUNCTION `EMPORCUST_GetAccVal`(`p_AccName` BIGINT, `p_crunseType` INT) RETURNS BIGINT DETERMINISTIC
BEGIN
DECLARE v_IsDefault BIT;
DECLARE v_AccCreditVal DECIMAL(15, 3);
DECLARE v_AccdebitVal DECIMAL(15, 3);
DECLARE v_AccVal DECIMAL(15, 3);
    SELECT aa.IsDefault INTO v_IsDefault FROM
            CurrencyMainTb AS aa
    WHERE
            aa.ID = p_crunseType
 ORDER BY aa.ID DESC LIMIT 1;
    IF v_IsDefault = 1
       THEN
        SELECT IFNULL(SUM(a.Credit), 0.000) INTO v_AccCreditVal FROM
               `ExSyAccounts2026`.`AccSafeActivityTb` AS a
            LEFT JOIN
              AccountsTb AS b
                ON a.AccIDFrom = b.AccID
        WHERE
                b.AccID = p_AccName;
        SELECT IFNULL(SUM(a.Debit), 0.000) INTO v_AccdebitVal FROM
                `ExSyAccounts2026`.`AccSafeActivityTb` AS a
            LEFT JOIN
              AccountsTb AS b
                ON a.AccIDFrom = b.AccID
        WHERE
                b.AccID = p_AccName;
SET v_AccVal = v_AccCreditVal - v_AccdebitVal;
      END IF;
    IF v_IsDefault = 0
       THEN
        SELECT IFNULL(SUM(a.Credit), 0.000) INTO v_AccCreditVal FROM
                `ExSyAccountsCurrency2026`.`AccSafeActivityTbCurrency` AS a
            LEFT JOIN
              AccountsTb AS b
                ON a.AccIDFrom = b.AccID
        WHERE
                b.AccID = p_AccName
                AND CurrencyID = p_crunseType;

        SELECT IFNULL(SUM(a.Debit), 0.000) INTO v_AccdebitVal FROM
                `ExSyAccountsCurrency2026`.`AccSafeActivityTbCurrency` AS a
            LEFT JOIN
              AccountsTb AS b
                ON a.AccIDFrom = b.AccID
        WHERE
                b.AccID = p_AccName
                AND CurrencyID = p_crunseType;
SET v_AccVal = v_AccdebitVal - v_AccCreditVal;
      END IF;
    IF v_AccVal IS NULL
       THEN
SET v_AccVal = 0.000;
      END IF;
    RETURN v_AccVal;
  END //
DELIMITER ;

