DROP FUNCTION IF EXISTS `EMPORCUST_GetAccValCashOnly`;
DELIMITER //
CREATE FUNCTION `EMPORCUST_GetAccValCashOnly`(`p_AccName` BIGINT, `p_crunseType` INT, `p_LoadType` INT) RETURNS DECIMAL(15,3) DETERMINISTIC
BEGIN
DECLARE v_IsDefault BIT;
DECLARE v_AccCreditVal DECIMAL(15, 3);
DECLARE v_AccdebitVal DECIMAL(15, 3);
DECLARE v_AccVal DECIMAL(15, 3);
    SELECT aa.IsDefault INTO v_IsDefault FROM
            CurrencyMainTb AS aa
    WHERE
            aa.ID = p_crunseType
 ORDER BY aa.ID DESC LIMIT 1;
    IF (p_LoadType = 5
      OR
      p_LoadType = 6
      OR
      p_LoadType = 7
      OR
      p_LoadType = 8
      OR
      p_LoadType = 29
      OR
      p_LoadType = 33
      OR
      p_LoadType = 28
      OR
      p_LoadType = 32
      OR
      p_LoadType = 63
      OR
      p_LoadType = 64
      OR
      p_LoadType = 34
      OR
      p_LoadType = 35
      OR
      p_LoadType = 36
      OR
      p_LoadType = 37
      OR
      p_LoadType = 41
      OR
      p_LoadType = 46
      OR
      p_LoadType = 49)
       THEN
        IF v_IsDefault = 1
           THEN
            SELECT IFNULL(SUM(a.Credit), 0.000) INTO v_AccCreditVal FROM
                    ExSyAccounts_AccSafeActivityTb AS a
                INNER JOIN
                  AccountsTb AS b
                    ON a.AccIDFrom = b.AccID
            WHERE
                    b.AccID = p_AccName
                    AND a.IsBank = 0;
            SELECT IFNULL(SUM(a.Debit), 0.000) INTO v_AccdebitVal FROM
                    ExSyAccounts_AccSafeActivityTb AS a
                INNER JOIN
                  AccountsTb AS b
                    ON a.AccIDFrom = b.AccID
            WHERE
                    b.AccID = p_AccName
                    AND a.IsBank = 0;
SET v_AccVal = v_AccCreditVal - v_AccdebitVal;
          END IF;
        IF v_IsDefault = 0
           THEN
            SELECT IFNULL(SUM(a.Credit), 0.000) INTO v_AccCreditVal FROM
                    ExSyAccountsCurrency_AccSafeActivityTb AS a
                INNER JOIN
                  AccountsTb AS b
                    ON a.AccIDFrom = b.AccID
            WHERE
                    b.AccID = p_AccName
                    AND CurrencyID = p_crunseType;


            SELECT IFNULL(SUM(a.Debit), 0.000) INTO v_AccdebitVal FROM
                    ExSyAccountsCurrency_AccSafeActivityTb AS a
                INNER JOIN
                  AccountsTb AS b
                    ON a.AccIDFrom = b.AccID
            WHERE
                    b.AccID = p_AccName
                    AND CurrencyID = p_crunseType;
SET v_AccVal = v_AccdebitVal - v_AccCreditVal;
          END IF;
      END IF;
    IF (p_LoadType = 16
      OR
      p_LoadType = 17
      OR
      p_LoadType = 18
      OR
      p_LoadType = 19
      OR
      p_LoadType = 47
      OR
      p_LoadType = 48)
       THEN
        IF v_IsDefault = 1
           THEN
            SELECT IFNULL(SUM(a.Credit), 0.000) INTO v_AccCreditVal FROM
                    ExSyAccounts_AccSafeActivityTb AS a
                INNER JOIN
                  AccountsTb AS b
                    ON a.AccIDFrom = b.AccID
            WHERE
                    b.AccID = p_AccName
                    AND a.IsBank = 1;
            SELECT IFNULL(SUM(a.Debit), 0.000) INTO v_AccdebitVal FROM
                    ExSyAccounts_AccSafeActivityTb AS a
                INNER JOIN
                  AccountsTb AS b
                    ON a.AccIDFrom = b.AccID
            WHERE
                    b.AccID = p_AccName
                    AND (a.IsBank = 1 OR a.IsBank = 2);
SET v_AccVal =   v_AccCreditVal - v_AccdebitVal;
          END IF;
        IF v_IsDefault = 0
           THEN
            SELECT IFNULL(SUM(a.Credit), 0.000) INTO v_AccCreditVal FROM
                    ExSyAccountsCurrency_AccSafeActivityTb AS a
                INNER JOIN
                  AccountsTb AS b
                    ON a.AccIDFrom = b.AccID
            WHERE
                    b.AccID = p_AccName
                    AND CurrencyID = p_crunseType;
            SELECT IFNULL(SUM(a.Debit), 0.000) INTO v_AccdebitVal FROM
                    ExSyAccountsCurrency_AccSafeActivityTb AS a
                INNER JOIN
                  AccountsTb AS b
                    ON a.AccIDFrom = b.AccID
            WHERE
                    b.AccID = p_AccName
                    AND CurrencyID = p_crunseType;
SET v_AccVal = v_AccdebitVal - v_AccCreditVal;
          END IF;
      END IF;
    RETURN v_AccVal;
  END //
DELIMITER ;

