DROP FUNCTION IF EXISTS `EXET_GetSalePrice`;
DELIMITER //
CREATE FUNCTION `EXET_GetSalePrice`(`p_CurrencyTo` INT, `p_CurrencyFrom` INT, `p_AccountType` INT, `p_CountryID` INT, `p_BankID` INT) RETURNS DOUBLE DETERMINISTIC
BEGIN
DECLARE v_CurrencyPower INT;
DECLARE v_CurrencySalePrice FLOAT;
DECLARE v_CurrencyBuyPrice FLOAT;
DECLARE v_Get_Purchaseprice FLOAT;




        IF p_CurrencyTo = 1
           THEN
            SELECT b.SalePrice INTO v_Get_Purchaseprice FROM
                    NewCurrencyPricesOwnTb AS a
                INNER JOIN
                  NewCurrencyPriceOwnDetailsTb AS b
                    ON a.ID = b.CPID
                INNER JOIN
                  `CurrencyMainTb` AS c
                    ON b.CurrencyIDTo = c.ID
            WHERE
                    a.IsActive = 1
                    AND b.IsActive = 1
                    AND c.IsActive = 1
                    AND a.CurrencyIDFrom = p_CurrencyTo
                    AND b.CurrencyIDTo = p_CurrencyFrom
                    AND a.PriceType = 2
                    AND a.CountryID = p_CountryID
                    AND a.AccountType=p_AccountType;
          END IF;

        IF p_CurrencyTo <> 1
           THEN
            SELECT a.CurrencyPower INTO v_CurrencyPower FROM
                    NewCurrencyPriceOwnDetailsTb AS a
                INNER JOIN
                  NewCurrencyPricesOwnTb AS b
                    ON a.CPID = b.ID
            WHERE
                    a.CurrencyIDFrom = 1
                    AND a.CurrencyIDTo = p_CurrencyFrom
                    AND b.PriceType = 2
                    AND b.CountryID = p_CountryID
                    AND b.AccountType=p_AccountType;

            IF v_CurrencyPower = 1
               THEN
                SELECT a.BuyPrice INTO v_CurrencySalePrice FROM
                        NewCurrencyPriceOwnDetailsTb AS a
                    INNER JOIN
                      NewCurrencyPricesOwnTb AS b
                        ON a.CPID = b.ID
                WHERE
                        a.CurrencyIDFrom = 1
                        AND a.CurrencyIDTo = p_CurrencyTo
                        AND b.PriceType = 2
                        AND b.CountryID = p_CountryID
                        AND b.AccountType=p_AccountType;
                SELECT a.SalePrice INTO v_CurrencyBuyPrice FROM
                        NewCurrencyPriceOwnDetailsTb AS a
                    INNER JOIN
                      NewCurrencyPricesOwnTb AS b
                        ON a.CPID = b.ID
                WHERE
                        a.CurrencyIDFrom = 1
                        AND a.CurrencyIDTo = p_CurrencyFrom
                        AND b.PriceType = 2
                        AND b.CountryID = p_CountryID
                        AND b.AccountType=p_AccountType;
                SELECT CASE                                                     WHEN a.CurrencyPower = 0                                                       THEN                                                       v_CurrencySalePrice * v_CurrencyBuyPrice                                                     ELSE                                                     v_CurrencyBuyPrice / v_CurrencySalePrice                                             END INTO v_Get_Purchaseprice FROM
                        NewCurrencyPriceOwnDetailsTb AS a
                    INNER JOIN
                      NewCurrencyPricesOwnTb AS b
                        ON a.CPID = b.ID
                WHERE
                        a.CurrencyIDTo = p_CurrencyTo
                        AND b.PriceType = 2
                        AND b.CountryID = p_CountryID
                        AND b.AccountType=p_AccountType;
              END IF;

            IF v_CurrencyPower = 0
               THEN
                SELECT a.CurrencyPower INTO v_CurrencyPower FROM
                        NewCurrencyPriceOwnDetailsTb AS a
                    INNER JOIN
                      NewCurrencyPricesOwnTb AS b
                        ON a.CPID = b.ID
                WHERE
                        a.CurrencyIDFrom = 1
                        AND a.CurrencyIDTo = p_CurrencyFrom
                        AND b.PriceType = 2
                        AND b.CountryID = p_CountryID
                        AND b.AccountType=p_AccountType;
                SELECT a.SalePrice INTO v_CurrencySalePrice FROM
                        NewCurrencyPriceOwnDetailsTb AS a
                    INNER JOIN
                      NewCurrencyPricesOwnTb AS b
                        ON a.CPID = b.ID
                WHERE
                        a.CurrencyIDFrom = 1
                        AND a.CurrencyIDTo = p_CurrencyFrom
                        AND b.PriceType = 2
                        AND b.CountryID = p_CountryID
                        AND b.AccountType=p_AccountType;
                SELECT a.BuyPrice INTO v_CurrencyBuyPrice FROM
                        NewCurrencyPriceOwnDetailsTb AS a
                    INNER JOIN
                      NewCurrencyPricesOwnTb AS b
                        ON a.CPID = b.ID
                WHERE
                        a.CurrencyIDFrom = 1
                        AND a.CurrencyIDTo = p_CurrencyTo
                        AND b.PriceType = 2
                        AND b.CountryID = p_CountryID
                        AND b.AccountType=p_AccountType;
SET v_Get_Purchaseprice = v_CurrencySalePrice * v_CurrencyBuyPrice;
              END IF;

          END IF;



    RETURN IFNULL(v_Get_Purchaseprice, 0);
  END //
DELIMITER ;

DROP FUNCTION IF EXISTS `EXEX_Get_TransBuyprice`;
DELIMITER //
CREATE FUNCTION `EXEX_Get_TransBuyprice`(`p_CurrencyFrom` INT, `p_CurrencyTo` INT, `p_AccountType` INT, `p_BranchID` INT, `p_CountryID` INT, `p_BankID` INT) RETURNS DOUBLE DETERMINISTIC
BEGIN
DECLARE v_CurrencyPower INT;
DECLARE v_CurrencySalePrice FLOAT;
DECLARE v_CurrencyBuyPrice FLOAT;
DECLARE v_DefaolfCurr INT;
DECLARE v_Get_Purchaseprice FLOAT;


    IF (p_AccountType = 0 OR p_AccountType = 3)
       THEN
        IF (p_CurrencyTo = 1
          OR
          p_CurrencyFrom = 1)
           THEN
            SELECT b.BuyPrice INTO v_Get_Purchaseprice FROM
                    `NewCurrencyPricesOwnTb` AS a
                INNER JOIN
                  NewCurrencyPriceOwnDetailsTb AS b
                    ON a.ID = b.CPID
                INNER JOIN
                  `CurrencyMainTb` AS c
                    ON b.CurrencyIDTo = c.ID
            WHERE
                    a.IsActive = 1
                    AND b.IsActive = 1
                    AND c.IsActive = 1
                    AND (   b.CurrencyIDTo = p_CurrencyTo
                            OR b.CurrencyIDTo = p_CurrencyFrom)
                    AND a.PriceType = 2
                    AND a.AccountType = p_AccountType
					AND a.CountryID =p_CountryID
          AND BankID=p_BankID;
          END IF;
        IF p_CurrencyTo <> 1
          AND
          p_CurrencyFrom <> 1
           THEN
            SELECT a.CurrencyPower INTO v_CurrencyPower FROM
                    NewCurrencyPriceOwnDetailsTb AS a
                INNER JOIN
                  `NewCurrencyPricesOwnTb` AS b
                    ON a.CPID = b.ID
            WHERE
                    a.CurrencyIDFrom = 1
                    AND a.CurrencyIDTo = p_CurrencyFrom
                    AND b.PriceType = 2
                    AND b.AccountType = p_AccountType
					AND b.CountryID =p_CountryID
          AND BankID=p_BankID;
            IF v_CurrencyPower = 1
               THEN
                SELECT a.SalePrice INTO v_CurrencySalePrice FROM
                        NewCurrencyPriceOwnDetailsTb AS a
                    INNER JOIN
                      `NewCurrencyPricesOwnTb` AS b
                        ON a.CPID = b.ID
                WHERE
                        a.CurrencyIDFrom = 1
                        AND a.CurrencyIDTo = p_CurrencyTo
                        AND b.PriceType = 2
                        AND b.AccountType = p_AccountType
						AND b.CountryID =p_CountryID
            AND BankID=p_BankID;
                SELECT a.BuyPrice INTO v_CurrencyBuyPrice FROM
                        NewCurrencyPriceOwnDetailsTb AS a
                    INNER JOIN
                      `NewCurrencyPricesOwnTb` AS b
                        ON a.CPID = b.ID
                WHERE
                        a.CurrencyIDFrom = 1
                        AND a.CurrencyIDTo = p_CurrencyFrom
                        AND b.PriceType = 2
                        AND b.AccountType = p_AccountType
						AND b.CountryID =p_CountryID
            AND BankID=p_BankID;
                SELECT CASE                                                     WHEN a.CurrencyPower = 0                                                       THEN                                                       v_CurrencySalePrice * v_CurrencyBuyPrice                                                     ELSE                                                     v_CurrencyBuyPrice / v_CurrencySalePrice                                             END INTO v_Get_Purchaseprice FROM
                        NewCurrencyPriceOwnDetailsTb AS a
                    INNER JOIN
                      `NewCurrencyPricesOwnTb` AS b
                        ON a.CPID = b.ID
                WHERE
                        a.CurrencyIDTo = p_CurrencyTo
                        AND b.PriceType = 2
                        AND b.AccountType = p_AccountType
						AND b.CountryID =p_CountryID
            AND BankID=p_BankID;
              END IF;
            IF v_CurrencyPower = 0
               THEN
                SELECT a.CurrencyPower INTO v_CurrencyPower FROM
                        NewCurrencyPriceOwnDetailsTb AS a
                    INNER JOIN
                      `NewCurrencyPricesOwnTb` AS b
                        ON a.CPID = b.ID
                WHERE
                        a.CurrencyIDFrom = 1
                        AND a.CurrencyIDTo = p_CurrencyFrom
                        AND b.PriceType = 2
                        AND b.AccountType = p_AccountType
						AND b.CountryID =p_CountryID
            AND BankID=p_BankID;
                SELECT a.BuyPrice INTO v_CurrencySalePrice FROM
                        NewCurrencyPriceOwnDetailsTb AS a
                    INNER JOIN
                      `NewCurrencyPricesOwnTb` AS b
                        ON a.CPID = b.ID
                WHERE
                        a.CurrencyIDFrom = 1
                        AND a.CurrencyIDTo = p_CurrencyFrom
                        AND b.PriceType = 2
                        AND b.AccountType = p_AccountType
						AND b.CountryID =p_CountryID
            AND BankID=p_BankID;
                SELECT a.SalePrice INTO v_CurrencyBuyPrice FROM
                        NewCurrencyPriceOwnDetailsTb AS a
                    INNER JOIN
                      `NewCurrencyPricesOwnTb` AS b
                        ON a.CPID = b.ID
                WHERE
                        a.CurrencyIDFrom = 1
                        AND a.CurrencyIDTo = p_CurrencyTo
                        AND b.PriceType = 2
                        AND b.AccountType = p_AccountType
						AND b.CountryID =p_CountryID
            AND BankID=p_BankID;
SET v_Get_Purchaseprice = v_CurrencySalePrice * v_CurrencyBuyPrice;
              END IF;
          END IF;
      END IF;
    IF p_AccountType = 1
       THEN
        IF (p_CurrencyTo = 1
          OR
          p_CurrencyFrom = 1)
           THEN
            SELECT b.BuyPrice INTO v_Get_Purchaseprice FROM
                    `NewCurrencyPricesOwnTb` AS a
                INNER JOIN
                  NewCurrencyPriceOwnDetailsTb AS b
                    ON a.ID = b.CPID
                INNER JOIN
                  `CurrencyMainTb` AS c
                    ON b.CurrencyIDTo = c.ID
            WHERE
                    a.IsActive = 1
                    AND b.IsActive = 1
                    AND c.IsActive = 1
                    AND (   b.CurrencyIDTo = p_CurrencyTo
                            OR b.CurrencyIDTo = p_CurrencyFrom)
                    AND a.PriceType = 2
                    AND a.BranchID = p_BranchID
                    AND a.AccountType = p_AccountType
					AND a.CountryID =p_CountryID
          AND BankID=p_BankID;
          END IF;
        IF (p_CurrencyTo <> 1
          AND
          p_CurrencyFrom <> 1)
           THEN
            SELECT a.CurrencyPower INTO v_CurrencyPower FROM
                    NewCurrencyPriceOwnDetailsTb AS a
                INNER JOIN
                  `NewCurrencyPricesOwnTb` AS b
                    ON a.CPID = b.ID
            WHERE
                    a.CurrencyIDFrom = 1
                    AND a.CurrencyIDTo = p_CurrencyFrom
                    AND b.PriceType = 2
                    AND b.BranchID = p_BranchID
                    AND b.AccountType = p_AccountType
					AND b.CountryID =p_CountryID
          AND BankID=p_BankID;
            IF v_CurrencyPower = 1
               THEN
                SELECT a.SalePrice INTO v_CurrencySalePrice FROM
                        NewCurrencyPriceOwnDetailsTb AS a
                    INNER JOIN
                      `NewCurrencyPricesOwnTb` AS b
                        ON a.CPID = b.ID
                WHERE
                        a.CurrencyIDFrom = 1
                        AND a.CurrencyIDTo = p_CurrencyTo
                        AND b.PriceType = 2
                        AND b.BranchID = p_BranchID
                        AND b.AccountType = p_AccountType
						AND b.CountryID =p_CountryID
            AND BankID=p_BankID;
                SELECT a.BuyPrice INTO v_CurrencyBuyPrice FROM
                        NewCurrencyPriceOwnDetailsTb AS a
                    INNER JOIN
                      `NewCurrencyPricesOwnTb` AS b
                        ON a.CPID = b.ID
                WHERE
                        a.CurrencyIDFrom = 1
                        AND a.CurrencyIDTo = p_CurrencyFrom
                        AND b.PriceType = 2
                        AND b.BranchID = p_BranchID
                        AND b.AccountType = p_AccountType
						AND b.CountryID =p_CountryID
            AND BankID=p_BankID;
                SELECT CASE                                                     WHEN a.CurrencyPower = 0                                                       THEN                                                       v_CurrencySalePrice * v_CurrencyBuyPrice                                                     ELSE                                                     v_CurrencyBuyPrice / v_CurrencySalePrice                                             END INTO v_Get_Purchaseprice FROM
                        NewCurrencyPriceOwnDetailsTb AS a
                    INNER JOIN
                      `NewCurrencyPricesOwnTb` AS b
                        ON a.CPID = b.ID
                WHERE
                        a.CurrencyIDTo = p_CurrencyTo
                        AND b.PriceType = 2
                        AND b.BranchID = p_BranchID
                        AND b.AccountType = p_AccountType
						AND b.CountryID =p_CountryID
            AND BankID=p_BankID;
              END IF;
            IF v_CurrencyPower = 0
               THEN
                SELECT a.CurrencyPower INTO v_CurrencyPower FROM
                        NewCurrencyPriceOwnDetailsTb AS a
                    INNER JOIN
                      `NewCurrencyPricesOwnTb` AS b
                        ON a.CPID = b.ID
                WHERE
                        a.CurrencyIDFrom = 1
                        AND a.CurrencyIDTo = p_CurrencyFrom
                        AND b.PriceType = 2
                        AND b.BranchID = p_BranchID
                        AND b.AccountType = p_AccountType
						AND b.CountryID =p_CountryID
            AND BankID=p_BankID;
                SELECT a.BuyPrice INTO v_CurrencySalePrice FROM
                        NewCurrencyPriceOwnDetailsTb AS a
                    INNER JOIN
                      `NewCurrencyPricesOwnTb` AS b
                        ON a.CPID = b.ID
                WHERE
                        a.CurrencyIDFrom = 1
                        AND a.CurrencyIDTo = p_CurrencyFrom
                        AND b.PriceType = 2
                        AND b.BranchID = p_BranchID
                        AND b.AccountType = p_AccountType
						AND b.CountryID =p_CountryID
            AND BankID=p_BankID;
                SELECT a.SalePrice INTO v_CurrencyBuyPrice FROM
                        NewCurrencyPriceOwnDetailsTb AS a
                    INNER JOIN
                      `NewCurrencyPricesOwnTb` AS b
                        ON a.CPID = b.ID
                WHERE
                        a.CurrencyIDFrom = 1
                        AND a.CurrencyIDTo = p_CurrencyTo
                        AND b.PriceType = 2
                        AND b.BranchID = p_BranchID
                        AND b.AccountType = p_AccountType
						AND b.CountryID =p_CountryID
            AND BankID=p_BankID;
SET v_Get_Purchaseprice = v_CurrencySalePrice * v_CurrencyBuyPrice;
              END IF;
          END IF;
      END IF;


    RETURN IFNULL(v_Get_Purchaseprice, 0);

  END //
DELIMITER ;

DROP FUNCTION IF EXISTS `EXEX_Get_Transprice`;
DELIMITER //
CREATE FUNCTION `EXEX_Get_Transprice`(`p_CurrencyFrom` INT, `p_CurrencyTo` INT, `p_AccountType` INT, `p_BranchID` INT) RETURNS DOUBLE DETERMINISTIC
BEGIN
DECLARE v_CurrencyPower INT;
DECLARE v_CurrencySalePrice FLOAT;
DECLARE v_CurrencyBuyPrice FLOAT;
DECLARE v_DefaolfCurr int;
DECLARE v_Get_Purchaseprice FLOAT;


				If p_AccountType=0
				 THEN
				IF p_CurrencyTo = 1 OR p_CurrencyFrom=1
					 THEN
						SELECT b.SalePrice INTO v_Get_Purchaseprice FROM
								`NewCurrencyPricesOwnTb` AS a
							INNER JOIN
								NewCurrencyPriceOwnDetailsTb AS b
									ON a.ID = b.CPID
							INNER JOIN
								`CurrencyMainTb` AS c
									ON b.CurrencyIDTo = c.ID
						WHERE
								a.IsActive = 1
								AND b.IsActive = 1
								AND c.IsActive = 1
								AND (b.CurrencyIDTo =  p_CurrencyTo or b.CurrencyIDTo =p_CurrencyFrom)
								AND a.PriceType=2;
					END IF;
				IF p_CurrencyTo <> 1 AND p_CurrencyFrom<>1
					 THEN
						SELECT a.CurrencyPower INTO v_CurrencyPower FROM
								NewCurrencyPriceOwnDetailsTb AS a
								INNER JOIN
								`NewCurrencyPricesOwnTb` AS b
								ON a.CPID = b.ID
						WHERE
								a.CurrencyIDFrom = 1
								AND a.CurrencyIDTo = p_CurrencyFrom
								AND b.PriceType=2;
						IF v_CurrencyPower = 1
							 THEN
								SELECT a.SalePrice INTO v_CurrencySalePrice FROM
										NewCurrencyPriceOwnDetailsTb AS a
										INNER JOIN
								`NewCurrencyPricesOwnTb` AS b
								ON a.CPID = b.ID
								WHERE
										a.CurrencyIDFrom = 1
										AND a.CurrencyIDTo = p_CurrencyTo
										AND b.PriceType=2;

								SELECT a.BuyPrice INTO v_CurrencyBuyPrice FROM
										NewCurrencyPriceOwnDetailsTb AS a
										INNER JOIN
								`NewCurrencyPricesOwnTb` AS b
								ON a.CPID = b.ID
								WHERE
										a.CurrencyIDFrom = 1
										AND a.CurrencyIDTo = p_CurrencyFrom
										AND b.PriceType=2;
								SELECT CASE 																	WHEN a.CurrencyPower = 0 																		THEN 																		v_CurrencySalePrice * v_CurrencyBuyPrice 																	ELSE 																	v_CurrencyBuyPrice / v_CurrencySalePrice 															END INTO v_Get_Purchaseprice FROM
										NewCurrencyPriceOwnDetailsTb AS a
										INNER JOIN
								`NewCurrencyPricesOwnTb` AS b
								ON a.CPID = b.ID
								WHERE
										a.CurrencyIDTo = p_CurrencyTo
										AND b.PriceType=2;
							END IF;
						IF v_CurrencyPower = 0
							 THEN
								SELECT a.CurrencyPower INTO v_CurrencyPower FROM
										NewCurrencyPriceOwnDetailsTb AS a
										INNER JOIN
								`NewCurrencyPricesOwnTb` AS b
								ON a.CPID = b.ID
								WHERE
										a.CurrencyIDFrom = 1
										AND a.CurrencyIDTo = p_CurrencyFrom
										AND b.PriceType=2;
								SELECT a.BuyPrice INTO v_CurrencySalePrice FROM
										NewCurrencyPriceOwnDetailsTb AS a
										INNER JOIN
								`NewCurrencyPricesOwnTb` AS b
								ON a.CPID = b.ID
								WHERE
										a.CurrencyIDFrom = 1
										AND a.CurrencyIDTo = p_CurrencyFrom
										AND b.PriceType=2;
								SELECT a.SalePrice INTO v_CurrencyBuyPrice FROM
										NewCurrencyPriceOwnDetailsTb AS a
										INNER JOIN
								`NewCurrencyPricesOwnTb` AS b
								ON a.CPID = b.ID
								WHERE
										a.CurrencyIDFrom = 1
										AND a.CurrencyIDTo = p_CurrencyTo
										AND b.PriceType=2;
SET v_Get_Purchaseprice = v_CurrencySalePrice * v_CurrencyBuyPrice;
							END IF;
					END IF;
					END IF;



		        If p_AccountType=1
				 THEN
				IF p_CurrencyTo = 1 AND p_CurrencyFrom=1
					 THEN
						SELECT b.BuyPrice INTO v_Get_Purchaseprice FROM
								`NewCurrencyPricesOwnTb` AS a
							INNER JOIN
								NewCurrencyPriceOwnDetailsTb AS b
									ON a.ID = b.CPID
							INNER JOIN
								`CurrencyMainTb` AS c
									ON b.CurrencyIDTo = c.ID
						WHERE
								a.IsActive = 1
								AND b.IsActive = 1
								AND c.IsActive = 1
								AND (b.CurrencyIDTo =  p_CurrencyTo or b.CurrencyIDTo =p_CurrencyFrom)
								AND a.PriceType=2
								AND a.BranchID=p_BranchID;
					END IF;
				IF p_CurrencyTo <> 1 or p_CurrencyFrom<>1
					 THEN
						SELECT a.CurrencyPower INTO v_CurrencyPower FROM
								NewCurrencyPriceOwnDetailsTb AS a
								INNER JOIN
								`NewCurrencyPricesOwnTb` AS b
								ON a.CPID = b.ID
						WHERE
								a.CurrencyIDFrom = 1
								AND a.CurrencyIDTo = p_CurrencyFrom
								AND b.PriceType=2
								AND b.BranchID=p_BranchID;
						IF v_CurrencyPower = 1
							 THEN
								SELECT a.SalePrice INTO v_CurrencySalePrice FROM
										NewCurrencyPriceOwnDetailsTb AS a
										INNER JOIN
								`NewCurrencyPricesOwnTb` AS b
								ON a.CPID = b.ID
								WHERE
										a.CurrencyIDFrom = 1
										AND a.CurrencyIDTo = p_CurrencyTo
										AND b.PriceType=2
										AND b.BranchID=p_BranchID;
								SELECT a.BuyPrice INTO v_CurrencyBuyPrice FROM
										NewCurrencyPriceOwnDetailsTb AS a
										INNER JOIN
								`NewCurrencyPricesOwnTb` AS b
								ON a.CPID = b.ID
								WHERE
										a.CurrencyIDFrom = 1
										AND a.CurrencyIDTo = p_CurrencyFrom
										AND b.PriceType=2
										AND b.BranchID=p_BranchID;
								SELECT CASE 																	WHEN a.CurrencyPower = 0 																		THEN 																		v_CurrencySalePrice * v_CurrencyBuyPrice 																	ELSE 																	v_CurrencyBuyPrice / v_CurrencySalePrice 															END INTO v_Get_Purchaseprice FROM
										NewCurrencyPriceOwnDetailsTb AS a
										INNER JOIN
								`NewCurrencyPricesOwnTb` AS b
								ON a.CPID = b.ID
								WHERE
										a.CurrencyIDTo = p_CurrencyTo
										AND b.PriceType=2
										AND b.BranchID=p_BranchID;
							END IF;
						IF v_CurrencyPower = 0
							 THEN
								SELECT a.CurrencyPower INTO v_CurrencyPower FROM
										NewCurrencyPriceOwnDetailsTb AS a
										INNER JOIN
								`NewCurrencyPricesOwnTb` AS b
								ON a.CPID = b.ID
								WHERE
										a.CurrencyIDFrom = 1
										AND a.CurrencyIDTo = p_CurrencyFrom
										AND b.PriceType=2;
								SELECT a.BuyPrice INTO v_CurrencySalePrice FROM
										NewCurrencyPriceOwnDetailsTb AS a
										INNER JOIN
								`NewCurrencyPricesOwnTb` AS b
								ON a.CPID = b.ID
								WHERE
										a.CurrencyIDFrom = 1
										AND a.CurrencyIDTo = p_CurrencyFrom
										AND b.PriceType=2
										AND b.BranchID=p_BranchID;
								SELECT a.SalePrice INTO v_CurrencyBuyPrice FROM
										NewCurrencyPriceOwnDetailsTb AS a
										INNER JOIN
								`NewCurrencyPricesOwnTb` AS b
								ON a.CPID = b.ID
								WHERE
										a.CurrencyIDFrom = 1
										AND a.CurrencyIDTo = p_CurrencyTo
										AND b.PriceType=2
										AND b.BranchID=p_BranchID;
SET v_Get_Purchaseprice = v_CurrencySalePrice * v_CurrencyBuyPrice;
							END IF;
					END IF;
					END IF;

		RETURN IFNULL(v_Get_Purchaseprice, 0);

	END //
DELIMITER ;

