DROP FUNCTION IF EXISTS `ExtraCommission_AccEmpDebit`;
DELIMITER //
CREATE FUNCTION `ExtraCommission_AccEmpDebit`(`p_SafeID` LONGTEXT, `p_InsertDate` DATE) RETURNS DECIMAL(12,3) DETERMINISTIC
BEGIN
DECLARE v_excom decimal(12,3);
SELECT IFNULL(sum(a.Debit),0) INTO v_excom FROM AccEmpActivityTb a WHERE a.OperationTypeID	<>6 AND A.IsActive=1 AND a.ISID	=p_SafeID AND a.insertdate=p_InsertDate GROUP BY	a.isid
 ORDER BY a.isid DESC LIMIT 1;
RETURN	v_excom;
END //
DELIMITER ;

DROP FUNCTION IF EXISTS `Get_AllBranchSafesVal`;
DELIMITER //
CREATE FUNCTION `Get_AllBranchSafesVal`(`p_BranchID` INT) RETURNS DECIMAL(15,3) DETERMINISTIC
BEGIN
DECLARE v_EmpSafes DECIMAL(15, 3);
DECLARE v_MainSafes DECIMAL(15, 3);
DECLARE v_AccVal DECIMAL(15, 3);


    SELECT IFNULL(SUM(A.Debit), 0) - IFNULL(SUM(A.Credit), 0) INTO v_MainSafes FROM
            ExSyAccounts_AccSafeActivityTb AS A
        JOIN
          AccountsTb AS b
            ON a.AccIDFrom = b.AccID
    WHERE
            A.IsActive = 1
            AND A.AccBranchID = p_BranchID
            AND b.AccParent = 1010101;

    SELECT IFNULL(SUM(A.Debit), 0) - IFNULL(SUM(A.Credit), 0) INTO v_EmpSafes FROM
            ExSyAccounts_AccSafeActivityTb AS A
        JOIN
          AccountsTb AS b
            ON A.AccIDFrom = b.AccID
    WHERE
            A.IsActive = 1
            AND A.AccBranchID = p_BranchID
            AND LEFT(b.AccParent, 5) = 10104
            AND a.DailyClosed = 0
    GROUP BY
            b.AccParent
 ORDER BY b.AccParent DESC LIMIT 1;
SET v_AccVal=IFNULL(v_MainSafes+v_EmpSafes,0);
    RETURN v_AccVal;
  END //
DELIMITER ;

DROP FUNCTION IF EXISTS `Get_CurrencyPower`;
DELIMITER //
CREATE FUNCTION `Get_CurrencyPower`(`p_RecievedCurrencyID` INT, `p_CountryIDTo` INT, `p_DeliveredCurrencyID` INT, `p_AccountType` INT, `p_PriceType` INT, `p_BranchID` INT) RETURNS TINYINT(1) DETERMINISTIC
BEGIN
DECLARE v_Get_CurrencyPower Bit;

 SELECT A.CurrencyPower INTO v_Get_CurrencyPower FROM
                      NewCurrencyPriceOwnDetailsTb AS a
                  INNER JOIN
                    NewCurrencyPricesOwnTb AS b
                      ON a.CPID = b.ID
              WHERE
                      a.CurrencyIDFrom = p_RecievedCurrencyID
                      AND b.PriceType = p_PriceType
                      AND b.AccountType = p_AccountType
                      AND b.CountryID = p_CountryIDTo
                      AND a.CurrencyIDTo = p_DeliveredCurrencyID
					  And b.BranchID =p_BranchID;

		RETURN IFNULL(v_Get_CurrencyPower,2);

	END //
DELIMITER ;

DROP FUNCTION IF EXISTS `GET_OverAllTotal1`;
DELIMITER //
CREATE FUNCTION `GET_OverAllTotal1`(`p_TypeMov` INT, `p_CurrencyTo` INT, `p_BranchID` INT, `p_GET_OverA` INT) RETURNS DECIMAL(18,3) DETERMINISTIC
BEGIN
DECLARE v_GET_OverAllTotal decimal(18,3);
DECLARE v_IsDefault INT;

  SELECT IsDefault INTO v_IsDefault FROM CurrencyMainTb AS CMT
	where cmt.id=p_CurrencyTo
 ORDER BY CMT.ID DESC LIMIT 1;

  if  v_IsDefault = 1
   THEN
  if p_TypeMov =0
   THEN
  if p_GET_OverA = 0
   THEN

  SELECT IFNULL(SUM (A.Debit ) ,0.000) INTO v_GET_OverAllTotal FROM ExSyAccounts_AccSafeActivityTb as a
  inner join CustomersTb as b on a.AccIDFrom = b.AccID
  where a.IsActive =1 and a.AccBranchID= p_BranchID;

  END IF;


    if p_GET_OverA = 1
   THEN

  SELECT IFNULL(SUM (A.Credit ) , 0.000) INTO v_GET_OverAllTotal FROM ExSyAccounts_AccSafeActivityTb as a
  inner join CustomersTb as b on a.AccIDFrom = b.AccID
  where a.IsActive =1 and a.AccBranchID= p_BranchID;

  END IF;


   if p_GET_OverA = 2
   THEN

  SELECT IFNULL(SUM (A.Credit ) , 0.000)    - IFNULL(SUM (A.Debit ) ,0.000) INTO v_GET_OverAllTotal FROM ExSyAccounts_AccSafeActivityTb as a
  inner join CustomersTb as b on a.AccIDFrom = b.AccID
  where a.IsActive =1 and a.AccBranchID= p_BranchID;

  END IF;

  END IF;

  if p_TypeMov =1
   THEN
  if p_GET_OverA = 0
   THEN

  SELECT IFNULL(SUM (A.Debit ) ,0.000) INTO v_GET_OverAllTotal FROM ExSyAccounts_AccSafeActivityTb as a
  inner join AccountsTb  as b on a.AccIDFrom = b.AccID
inner join EmployeeTb as c on b.AccName = c.EMPNAME
  where a.IsActive =1 and a.AccBranchID= p_BranchID;

  END IF;

    if p_GET_OverA = 1
   THEN

  SELECT IFNULL(SUM (A.Credit ) , 0.000) INTO v_GET_OverAllTotal FROM ExSyAccounts_AccSafeActivityTb as a
 inner join AccountsTb  as b on a.AccIDFrom = b.AccID
inner join EmployeeTb as c on b.AccName = c.EMPNAME
  where a.IsActive =1 and a.AccBranchID= p_BranchID;

  END IF;


   if p_GET_OverA = 2
   THEN

  SELECT IFNULL(SUM (A.Credit ) , 0.000)    - IFNULL(SUM (A.Debit ) ,0.000) INTO v_GET_OverAllTotal FROM ExSyAccounts_AccSafeActivityTb as a
  inner join AccountsTb  as b on a.AccIDFrom = b.AccID
inner join EmployeeTb as c on b.AccName = c.EMPNAME
  where a.IsActive =1 and a.AccBranchID= p_BranchID;

  END IF;
  END IF;









  END IF;


  if  v_IsDefault = 0
   THEN
  if p_TypeMov =0
   THEN
  if p_GET_OverA = 0
   THEN

  SELECT IFNULL(SUM (A.Debit ) ,0.000) INTO v_GET_OverAllTotal FROM ExSyAccountsCurrency_AccSafeActivityTb as a
  inner join CustomersTb as b on a.AccIDFrom = b.AccID
  where a.IsActive =1 and a.AccBranchID= p_BranchID   and a.CurrencyID = p_CurrencyTo;

  END IF;


    if p_GET_OverA = 1
   THEN

  SELECT IFNULL(SUM (A.Credit ) , 0.000) INTO v_GET_OverAllTotal FROM ExSyAccountsCurrency_AccSafeActivityTb as a
  inner join CustomersTb as b on a.AccIDFrom = b.AccID
  where a.IsActive =1 and a.AccBranchID= p_BranchID   and a.CurrencyID = p_CurrencyTo;

  END IF;


   if p_GET_OverA = 2
   THEN

  SELECT IFNULL(SUM (A.Credit ) , 0.000)    - IFNULL(SUM (A.Debit ) ,0.000) INTO v_GET_OverAllTotal FROM ExSyAccountsCurrency_AccSafeActivityTb as a
  inner join CustomersTb as b on a.AccIDFrom = b.AccID
  where a.IsActive =1 and a.AccBranchID= p_BranchID   and a.CurrencyID = p_CurrencyTo;

  END IF;




  END IF;


  if p_TypeMov =1
   THEN
  if p_GET_OverA = 0
   THEN

  SELECT IFNULL(SUM (A.Debit ) ,0.000) INTO v_GET_OverAllTotal FROM  ExSyAccountsCurrency_AccSafeActivityTb as a
  inner join AccountsTb  as b on a.AccIDFrom = b.AccID
inner join EmployeeTb as c on b.AccName = c.EMPNAME
  where a.IsActive =1 and a.AccBranchID= p_BranchID    and a.CurrencyID = p_CurrencyTo
  HAVING   IFNULL(SUM (A.Credit ) , 0.000)   -  IFNULL(SUM (A.Debit ) ,0.000)   <=0;
  END IF;

    if p_GET_OverA = 1
   THEN

  SELECT IFNULL(SUM (A.Credit ) , 0.000) INTO v_GET_OverAllTotal FROM ExSyAccountsCurrency_AccSafeActivityTb as a
 inner join AccountsTb  as b on a.AccIDFrom = b.AccID
inner join EmployeeTb as c on b.AccName = c.EMPNAME
  where a.IsActive =1 and a.AccBranchID= p_BranchID    and a.CurrencyID = p_CurrencyTo
  HAVING   IFNULL(SUM (A.Credit ) , 0.000)   -  IFNULL(SUM (A.Debit ) ,0.000)   > 0;
  END IF;


   if p_GET_OverA = 2
   THEN

  SELECT IFNULL(SUM (A.Credit ) , 0.000)    - IFNULL(SUM (A.Debit ) ,0.000) INTO v_GET_OverAllTotal FROM  ExSyAccountsCurrency_AccSafeActivityTb as a
  inner join AccountsTb  as b on a.AccIDFrom = b.AccID
inner join EmployeeTb as c on b.AccName = c.EMPNAME
  where a.IsActive =1 and a.AccBranchID= p_BranchID   and a.CurrencyID = p_CurrencyTo;

  END IF;
  END IF;









  END IF;











 return  IFNULL(v_GET_OverAllTotal  , 0.000);
 END //
DELIMITER ;

DROP FUNCTION IF EXISTS `Get_Purchaseprice`;
DELIMITER //
CREATE FUNCTION `Get_Purchaseprice`(`p_CurrencyTo` INT, `p_CurrencyFrom` INT, `p_TupeBank` INT) RETURNS DOUBLE DETERMINISTIC
BEGIN
DECLARE v_CurrencyPower INT;
DECLARE v_CurrencySalePrice FLOAT;
DECLARE v_CurrencyBuyPrice FLOAT;
DECLARE v_Get_Purchaseprice FLOAT;

		IF p_TupeBank = 0
			 THEN
				IF p_CurrencyTo = 1
					 THEN
						SELECT b.BuyPrice INTO v_Get_Purchaseprice FROM
								`CurrencyPricesTb` AS a
							INNER JOIN
								CurrencyPriceDetailsTb AS b
									ON a.CurrencyIDFrom = b.CurrencyIDFrom
							INNER JOIN
								`CurrencyMainTb` AS c
									ON b.CurrencyIDTo = c.ID
						WHERE
								a.IsActive = 1
								AND b.IsActive = 1
								AND c.IsActive = 1
								AND a.CurrencyIDFrom = p_CurrencyTo
								AND b.CurrencyIDTo = p_CurrencyFrom;
					END IF;
				IF p_CurrencyTo <> 1
					 THEN
						SELECT a.CurrencyPower INTO v_CurrencyPower FROM
								CurrencyPriceDetailsTb AS a
						WHERE
								a.CurrencyIDFrom = 1
								AND a.CurrencyIDTo = p_CurrencyFrom;
						IF v_CurrencyPower = 1
							 THEN
								SELECT a.SalePrice INTO v_CurrencySalePrice FROM
										CurrencyPriceDetailsTb AS a
								WHERE
										a.CurrencyIDFrom = 1
										AND a.CurrencyIDTo = p_CurrencyTo;

								SELECT a.BuyPrice INTO v_CurrencyBuyPrice FROM
										CurrencyPriceDetailsTb AS a
								WHERE
										a.CurrencyIDFrom = 1
										AND a.CurrencyIDTo = p_CurrencyFrom;
								SELECT CASE 																	WHEN a.CurrencyPower = 0 																		THEN 																		v_CurrencySalePrice * v_CurrencyBuyPrice 																	ELSE 																	v_CurrencyBuyPrice / v_CurrencySalePrice 															END INTO v_Get_Purchaseprice FROM
										CurrencyPriceDetailsTb AS a
								WHERE
										a.CurrencyIDTo = p_CurrencyTo;
							END IF;
						IF v_CurrencyPower = 0
							 THEN
								SELECT a.CurrencyPower INTO v_CurrencyPower FROM
										CurrencyPriceDetailsTb AS a
								WHERE
										a.CurrencyIDFrom = 1
										AND a.CurrencyIDTo = p_CurrencyFrom;
								SELECT a.BuyPrice INTO v_CurrencySalePrice FROM
										CurrencyPriceDetailsTb AS a
								WHERE
										a.CurrencyIDFrom = 1
										AND a.CurrencyIDTo = p_CurrencyFrom;
								SELECT a.SalePrice INTO v_CurrencyBuyPrice FROM
										CurrencyPriceDetailsTb AS a
								WHERE
										a.CurrencyIDFrom = 1
										AND a.CurrencyIDTo = p_CurrencyTo;
SET v_Get_Purchaseprice = v_CurrencySalePrice * v_CurrencyBuyPrice;
							END IF;
					END IF;



			END IF;
		RETURN IFNULL(v_Get_Purchaseprice, 0);

	END //
DELIMITER ;

DROP FUNCTION IF EXISTS `Get_PurchaseSalePrice`;
DELIMITER //
CREATE FUNCTION `Get_PurchaseSalePrice`(`p_CurrencyTo` INT, `p_CurrencyFrom` INT, `p_TupeBank` INT) RETURNS DOUBLE DETERMINISTIC
BEGIN
DECLARE v_CurrencyPower INT;
DECLARE v_CurrencySalePrice FLOAT;
DECLARE v_CurrencyBuyPrice FLOAT;
DECLARE v_Get_Purchaseprice FLOAT;

		IF p_TupeBank = 0
			 THEN

				IF p_CurrencyTo = 1
					 THEN
						SELECT b.SalePrice INTO v_Get_Purchaseprice FROM
								`CurrencyPricesTb` AS a
							LEFT JOIN
								CurrencyPriceDetailsTb AS b
									ON a.CurrencyIDFrom = b.CurrencyIDFrom
							LEFT JOIN
								`CurrencyMainTb` AS c
									ON b.CurrencyIDTo = c.ID
						WHERE
								a.IsActive = 1
								AND b.IsActive = 1
								AND c.IsActive = 1
								AND a.CurrencyIDFrom = p_CurrencyTo
								AND b.CurrencyIDTo = p_CurrencyFrom;
					END IF;

				IF p_CurrencyTo <> 1
					 THEN
						SELECT a.CurrencyPower INTO v_CurrencyPower FROM
								CurrencyPriceDetailsTb AS a
						WHERE
								a.CurrencyIDFrom = 1
								AND a.CurrencyIDTo = p_CurrencyFrom;

						IF v_CurrencyPower = 1
							 THEN
								SELECT a.BuyPrice INTO v_CurrencySalePrice FROM
										CurrencyPriceDetailsTb AS a
								WHERE
										a.CurrencyIDFrom = 1
										AND a.CurrencyIDTo = p_CurrencyTo;
								SELECT a.SalePrice INTO v_CurrencyBuyPrice FROM
										CurrencyPriceDetailsTb AS a
								WHERE
										a.CurrencyIDFrom = 1
										AND a.CurrencyIDTo = p_CurrencyFrom;
								SELECT CASE 																	WHEN a.CurrencyPower = 0 																		THEN 																		v_CurrencySalePrice * v_CurrencyBuyPrice 																	ELSE 																	v_CurrencyBuyPrice / v_CurrencySalePrice 															END INTO v_Get_Purchaseprice FROM
										CurrencyPriceDetailsTb AS a
								WHERE
										a.CurrencyIDTo = p_CurrencyTo;
							END IF;

						IF v_CurrencyPower = 0
							 THEN
								SELECT a.CurrencyPower INTO v_CurrencyPower FROM
										CurrencyPriceDetailsTb AS a
								WHERE
										a.CurrencyIDFrom = 1
										AND a.CurrencyIDTo = p_CurrencyFrom;
								SELECT a.SalePrice INTO v_CurrencySalePrice FROM
										CurrencyPriceDetailsTb AS a
								WHERE
										a.CurrencyIDFrom = 1
										AND a.CurrencyIDTo = p_CurrencyFrom;
								SELECT a.BuyPrice INTO v_CurrencyBuyPrice FROM
										CurrencyPriceDetailsTb AS a
								WHERE
										a.CurrencyIDFrom = 1
										AND a.CurrencyIDTo = p_CurrencyTo;
SET v_Get_Purchaseprice = v_CurrencySalePrice * v_CurrencyBuyPrice;
							END IF;

					END IF;

			END IF;

		RETURN IFNULL(v_Get_Purchaseprice, 0);
	END //
DELIMITER ;

DROP FUNCTION IF EXISTS `GET_ReturnsSafeIDMovement`;
DELIMITER //
CREATE FUNCTION `GET_ReturnsSafeIDMovement`(`p_FirstCurrency` INT, `p_SAFTypeform` INT, `p_ISbaunk` INT, `p_SafTypeTo` INT, `p_SAFFACCTO` INT, `p_UeserInset` INT, `p_SaFACCount` INT, `p_typeFRom` INT, `p_BPrice1` DOUBLE, `p_Purchaseprice` DECIMAL(13,3)) RETURNS LONGTEXT DETERMINISTIC
BEGIN
DECLARE v_GETSafeIDMovement LONGTEXT;
DECLARE v_CRubsename LONGTEXT;
DECLARE v_SAFTypefo LONGTEXT;
DECLARE v_SAFFACC LONGTEXT;
DECLARE v_UeserI            LONGTEXT;


  SELECT AccName INTO v_SAFFACC FROM AccountsTb
  WHERE AccID=p_SAFFACCTO;
  SELECT a.CurCode INTO v_CRubsename FROM CurrencyMainTb AS a
  WHERE a.ID=p_FirstCurrency
 ORDER BY a.ID DESC LIMIT 1;
  SELECT AccName INTO v_SAFTypefo FROM AccountsTb
  WHERE AccID=p_SaFACCount;
  SELECT UName INTO v_UeserI FROM TB_Users
  WHERE USID=p_UeserInset
 ORDER BY TB_Users.USID DESC LIMIT 1;

  IF p_ISbaunk=0
   THEN
SET v_GETSafeIDMovement=CONCAT('عملية استرجاع', SPACE( 1 ), CASE              WHEN p_typeFRom=0              THEN 'شراء'              ELSE 'بيع'     END, SPACE( 1 ), CAST(p_BPrice1 AS CHAR), SPACE( 1 ), v_CRubsename, CHAR( 10 ), CHAR( 13 ), SPACE( 1 ), 'بسعر ', CAST(p_Purchaseprice AS CHAR), SPACE( 1 ), CASE              WHEN p_typeFRom=0              THEN CASE                       WHEN p_SAFTypeform=0                       THEN 'نقداً'                       ELSE CONCAT(CASE                                WHEN p_SAFTypeform=2151                                THEN 'من حساب الموظف '                                ELSE 'من '                       END, '  ', v_SAFTypefo)              END              ELSE ''     END, CHAR( 13 ), CHAR( 10 ), CASE              WHEN p_typeFRom=0              THEN CASE                       WHEN p_SafTypeTo<>0                       THEN CONCAT(SPACE( 1 ), '')                       ELSE SPACE( 1 )              END              ELSE CASE                       WHEN p_SafTypeTo<>0                       THEN CONCAT(SPACE( 1 ), ' ')                       ELSE 'نقدي '              END      END);
  END IF;

  RETURN IFNULL( v_GETSafeIDMovement, 'شراء عملة بالنقد الاجنبي' );
END //
DELIMITER ;

DROP FUNCTION IF EXISTS `GetAccline`;
DELIMITER //
CREATE FUNCTION `GetAccline`(`p_Parent` BIGINT) RETURNS INT DETERMINISTIC
BEGIN
DECLARE v_Accline int;
SELECT Accline INTO v_Accline FROM AccountsTb WHERE AccCode  = p_Parent;
IF v_Accline >= 0
 THEN
 SET v_Accline = v_Accline + (1);
 END IF;
IF v_Accline IS  NULL
 THEN
SET v_Accline =0;
END IF;


 RETURN  v_Accline;
END //
DELIMITER ;

DROP FUNCTION IF EXISTS `GetCostOf_Currency`;
DELIMITER //
CREATE FUNCTION `GetCostOf_Currency`(`p_PriceType` BIGINT, `p_CrunnceyID` INT, `p_BranchID` INT, `p_CountryID` INT) RETURNS DECIMAL(18,3) DETERMINISTIC
BEGIN
DECLARE v_AccVal DECIMAL(18, 3) DEFAULT 0;
DECLARE v_CurrencyPower INT DEFAULT 0;
DECLARE v_Credit DECIMAL(18,3);
DECLARE v_Debit DECIMAL(18,3);
DECLARE v_DLCredit DECIMAL(18,3);
DECLARE v_DLDebit DECIMAL(18,3);




    SELECT n.CurrencyPower INTO v_CurrencyPower FROM NewCurrencyPriceOwnDetailsTb n
    WHERE n.CurrencyIDTo = p_CrunnceyID LIMIT 1;




    SELECT SUM(i.Credit), SUM(i.Debit), SUM(i.DL_Credit), SUM(i.DL_Debit) INTO v_Credit, v_Debit, v_DLCredit, v_DLDebit FROM ExSyAccountsCurrency_AccSafeActivityTb i
    WHERE i.PriceType   = p_PriceType
      AND i.CurrencyID  = p_CrunnceyID
      AND i.AccBranchID = p_BranchID
      AND i.CountryID   = p_CountryID

      AND i.IsActive    = 1;




    IF (v_Credit IS NULL OR v_Debit IS NULL OR v_DLCredit IS NULL OR v_DLDebit IS NULL) THEN RETURN 0; END IF;

IF (v_CurrencyPower = 0)
 THEN
    SET v_AccVal =
    ABS( (v_Credit - v_Debit) / NULLIF((v_DLCredit - v_DLDebit), 0) );
 ELSEIF  (v_CurrencyPower = 1)
 THEN
    SET v_AccVal =
    ABS( (v_DLCredit - v_DLDebit) / NULLIF((v_Credit - v_Debit), 0) );
END IF;

    RETURN IFNULL(v_AccVal, 0.000);
END //
DELIMITER ;

DROP FUNCTION IF EXISTS `GetCostOf_Currency_More_Detials`;
DELIMITER //
CREATE FUNCTION `GetCostOf_Currency_More_Detials`(`p_PriceType` BIGINT, `p_CrunnceyID` INT, `p_BranchID` INT, `p_CountryID` INT, `p_BankID` INT) RETURNS DECIMAL(18,3) DETERMINISTIC
BEGIN
DECLARE v_AccVal DECIMAL(18, 3) DEFAULT 0;
DECLARE v_CurrencyPower INT DEFAULT 0;
DECLARE v_Credit DECIMAL(18,3);
DECLARE v_Debit DECIMAL(18,3);
DECLARE v_DLCredit DECIMAL(18,3);
DECLARE v_DLDebit DECIMAL(18,3);




    SELECT n.CurrencyPower INTO v_CurrencyPower FROM NewCurrencyPriceOwnDetailsTb n
    WHERE n.CurrencyIDTo = p_CrunnceyID LIMIT 1;

          IF NOT EXISTS (SELECT
                        1
                FROM
                        AccountsTb a
                WHERE
                        a.AccCode = p_BankID
                        AND a.AccParent = 10105)
             THEN
              SET p_BankID = 0;
            END IF;



    SELECT SUM(i.Credit), SUM(i.Debit), SUM(i.DL_Credit), SUM(i.DL_Debit) INTO v_Credit, v_Debit, v_DLCredit, v_DLDebit FROM ExSyAccountsCurrency_AccSafeActivityTb i
    WHERE i.PriceType   = p_PriceType
      AND i.CurrencyID  = p_CrunnceyID
      AND i.AccBranchID = p_BranchID
      AND i.CountryID   = p_CountryID

      AND i.IsActive    = 1
      AND ( (i.ParentFrom=p_BankID AND i.IsBank=1 ) OR (i.IsBank=0 AND p_BankID=0 ) );




    IF (v_Credit IS NULL OR v_Debit IS NULL OR v_DLCredit IS NULL OR v_DLDebit IS NULL) THEN RETURN 0; END IF;

IF (v_CurrencyPower = 0)
 THEN
    SET v_AccVal =
    ABS( (v_Credit - v_Debit) / NULLIF((v_DLCredit - v_DLDebit), 0) );
 ELSEIF  (v_CurrencyPower = 1)
 THEN
    SET v_AccVal =
    ABS( (v_DLCredit - v_DLDebit) / NULLIF((v_Credit - v_Debit), 0) );
END IF;

    RETURN IFNULL(v_AccVal, 0.000);
END //
DELIMITER ;

