DROP FUNCTION IF EXISTS `GETSafeIDMovement`;
DELIMITER //
CREATE FUNCTION `GETSafeIDMovement`(`p_FirstCurrency` INT, `p_SAFTypeform` INT, `p_ISbaunk` INT, `p_SafTypeTo` INT, `p_SAFFACCTO` INT, `p_UeserInset` INT, `p_SaFACCount` INT, `p_typeFRom` INT, `p_BPrice1` DOUBLE, `p_Purchaseprice` DECIMAL(13,3)) RETURNS LONGTEXT DETERMINISTIC
BEGIN
DECLARE v_GETSafeIDMovement LONGTEXT;
DECLARE v_CRubsename LONGTEXT;
DECLARE v_SAFTypefo LONGTEXT;
DECLARE v_SAFFACC LONGTEXT;
DECLARE v_UeserI			   LONGTEXT;


		SELECT AccName INTO v_SAFFACC FROM
				AccountsTb
		WHERE
				AccID = p_SAFFACCTO;

		SELECT a.CurCode INTO v_CRubsename FROM
				CurrencyMainTb AS a
		WHERE
				a.ID = p_FirstCurrency
 ORDER BY a.ID DESC LIMIT 1;
		SELECT AccName INTO v_SAFTypefo FROM
				AccountsTb
		WHERE
				AccID = p_SaFACCount;
		SELECT UName INTO v_UeserI FROM
				TB_Users
		WHERE
				USID = p_UeserInset
 ORDER BY TB_Users.USID DESC LIMIT 1;
		IF p_ISbaunk = 0
			 THEN
SET v_GETSafeIDMovement = CONCAT(CASE 													WHEN p_typeFRom = 0 														THEN 														'شراء' 													ELSE 													'بيع' 											END, SPACE(1), CAST(p_BPrice1 AS CHAR), SPACE(1), v_CRubsename, CHAR(10), CHAR(13), SPACE(1), 'بسعر ', CAST(p_Purchaseprice AS CHAR), SPACE(1), CASE 										  WHEN p_typeFRom = 0 											  THEN 											  CASE 													  WHEN p_SAFTypeform = 0 														  THEN 														  'نقداً' 													  ELSE 													  CONCAT(CASE 															  WHEN p_SAFTypeform = 2151 																  THEN 																  'من حساب الموظف ' 															  ELSE 															  'من ' 													  END, '  ', v_SAFTypefo) 											  END 										  ELSE 										  '' 								  END, CHAR(13), CHAR(10), CASE 													 WHEN p_typeFRom = 0 														 THEN 														 CASE 																 WHEN p_SafTypeTo <> 0 																	 THEN CONCAT(SPACE(1), ' لحساب') 																 ELSE 																 SPACE(1) 														 END 													 ELSE 													 CASE 															 WHEN p_SafTypeTo <> 0 																 THEN 																 CONCAT(SPACE(1), ' لحساب') 															 ELSE 															 'نقدي ' 													 END  											 END);
			END IF;
		RETURN IFNULL(v_GETSafeIDMovement, 'شراء عملة بالنقد الاجنبي');

	END //
DELIMITER ;

