BEGIN
DECLARE v_SumRBVAL decimal	(12,3);

SELECT IFNULL( sum(b.RBVal),0) INTO v_SumRBVAL FROM BenefitDistribution  AS b inner JOIN  AccEmpActivityTb a ON a.AccBranchID = b.RBID		 WHERE  a.OperationTypeID=6
 and a.SafeID	=p_SafeID and b.safeid = p_SafeID AND b.IsActive	=1 AND b.IsCanceled	=0  AND b.ISIDType	=1 and a.InsertDate	= p_date1	and a.TypeID	=1 AND a.IsCanceled	=0 GROUP BY	a.ISID
