DROP FUNCTION IF EXISTS `MainBranchSafesDetails_GetNetTotal`;
DELIMITER //
CREATE FUNCTION `MainBranchSafesDetails_GetNetTotal`(`p_AccName` BIGINT, `p_BranchID` INT, `p_CurrencyID` INT, `p_ID` BIGINT) RETURNS DECIMAL(15,3) DETERMINISTIC
BEGIN
DECLARE v_AccCreditVal DECIMAL(15, 3);
DECLARE v_AccdebitVal DECIMAL(15, 3);
DECLARE v_FinalAccVal DECIMAL(15, 3);
DECLARE v_NetVal DECIMAL(15, 3);
DECLARE v_AccVal DECIMAL(15, 3);
DECLARE v_MaxID bigint;
DECLARE v_CurrenDebit DECIMAL(15, 3);
DECLARE v_CurrenCredit DECIMAL(15, 3);
DECLARE v_IsDefault bit;

IF p_BranchID<>0
 THEN
		 SELECT a.IsDefault INTO v_IsDefault FROM CurrencyMainTb as a where a.id=p_CurrencyID
 ORDER BY a.ID DESC LIMIT 1;

		 if v_IsDefault=1
		  THEN
		 SELECT IFNULL(SUM(a.Credit), 0.000) INTO v_AccCreditVal FROM ExSyAccounts_AccSafeActivityTb AS a
          LEFT JOIN AccountsTb AS b ON a.AccIDFrom = b.AccID
          WHERE a.IsActive = 1
           AND b.AccActive = 1
           AND (a.CurrencyID   = p_CurrencyID OR a.CurrencyID	=13)
           AND a.AccIDFrom = p_AccName
           AND a.AccBranchID = p_BranchID
		   AND a.id<p_ID;
         SELECT IFNULL(SUM(a.debit), 0.000) INTO v_AccdebitVal FROM ExSyAccounts_AccSafeActivityTb AS a
          LEFT JOIN AccountsTb AS b ON a.AccIDFrom = b.AccID
         WHERE a.IsActive = 1
           AND b.AccActive = 1
           AND (a.CurrencyID   = p_CurrencyID OR a.CurrencyID	=13)
           AND a.AccIDFrom = p_AccName
           AND a.AccBranchID = p_BranchID
		   AND a.id<p_ID;


		   SELECT IFNULL(SUM(a.Credit), 0.000) INTO v_CurrenCredit FROM ExSyAccounts_AccSafeActivityTb AS a
          LEFT JOIN AccountsTb AS b ON a.AccIDFrom = b.AccID
          WHERE a.IsActive = 1
           AND b.AccActive = 1
           AND (a.CurrencyID   = p_CurrencyID OR a.CurrencyID	=13)
           AND a.AccIDFrom = p_AccName
           AND a.AccBranchID = p_BranchID
		   AND a.id=p_ID;
         SELECT IFNULL(SUM(a.debit), 0.000) INTO v_CurrenDebit FROM ExSyAccounts_AccSafeActivityTb AS a
          LEFT JOIN AccountsTb AS b ON a.AccIDFrom = b.AccID
         WHERE a.IsActive = 1
           AND b.AccActive = 1
           AND (a.CurrencyID   = p_CurrencyID OR a.CurrencyID	=13)
           AND a.AccIDFrom = p_AccName
           AND a.AccBranchID = p_BranchID
		   AND a.id=p_ID;
SET v_AccVal = v_AccdebitVal - v_AccCreditVal;
		   IF v_CurrenCredit > v_CurrenDebit
		    THEN
SET v_NetVal =v_AccVal - v_CurrenCredit;
		   END IF;
		   IF v_CurrenCredit < v_CurrenDebit
		    THEN
SET v_NetVal =v_AccVal + v_CurrenDebit;
		   END IF;
		   END IF;


		   if v_IsDefault=0
		  THEN
		 SELECT IFNULL(SUM(a.debit), 0.000) INTO v_AccCreditVal FROM ExSyAccountsCurrency_AccSafeActivityTb AS a
          LEFT JOIN AccountsTb AS b ON a.AccIDFrom = b.AccID
          WHERE a.IsActive = 1
           AND b.AccActive = 1
           AND (a.CurrencyID   = p_CurrencyID OR a.CurrencyID	=13)
           AND a.AccIDFrom = p_AccName
           AND a.AccBranchID = p_BranchID
		   AND a.id<p_ID;
         SELECT IFNULL(SUM(a.Credit), 0.000) INTO v_AccdebitVal FROM ExSyAccountsCurrency_AccSafeActivityTb AS a
          LEFT JOIN AccountsTb AS b ON a.AccIDFrom = b.AccID
         WHERE a.IsActive = 1
           AND b.AccActive = 1
           AND (a.CurrencyID   = p_CurrencyID OR a.CurrencyID	=13)
           AND a.AccIDFrom = p_AccName
           AND a.AccBranchID = p_BranchID
		   AND a.id<p_ID;


		   SELECT IFNULL(SUM(a.debit), 0.000) INTO v_CurrenCredit FROM ExSyAccountsCurrency_AccSafeActivityTb AS a
          LEFT JOIN AccountsTb AS b ON a.AccIDFrom = b.AccID
          WHERE a.IsActive = 1
           AND b.AccActive = 1
           AND (a.CurrencyID   = p_CurrencyID OR a.CurrencyID	=13)
           AND a.AccIDFrom = p_AccName
           AND a.AccBranchID = p_BranchID
		   AND a.id=p_ID;
         SELECT IFNULL(SUM(a.Credit), 0.000) INTO v_CurrenDebit FROM ExSyAccountsCurrency_AccSafeActivityTb AS a
          LEFT JOIN AccountsTb AS b ON a.AccIDFrom = b.AccID
         WHERE a.IsActive = 1
           AND b.AccActive = 1
           AND (a.CurrencyID   = p_CurrencyID OR a.CurrencyID	=13)
           AND a.AccIDFrom = p_AccName
           AND a.AccBranchID = p_BranchID
		   AND a.id=p_ID;
SET v_AccVal = v_AccdebitVal - v_AccCreditVal;
		   IF v_CurrenCredit > v_CurrenDebit
		    THEN
SET v_NetVal =v_AccVal - v_CurrenCredit;
		   END IF;
		   IF v_CurrenCredit < v_CurrenDebit
		    THEN
SET v_NetVal =v_AccVal + v_CurrenDebit;
		   END IF;
		   END IF;
END IF;

	 if p_BranchID=0
		  THEN
		 SELECT IFNULL(SUM(a.Credit), 0.000) INTO v_AccCreditVal FROM ExSyAccounts_AccSafeActivityTb AS a
          LEFT JOIN AccountsTb AS b ON a.AccIDFrom = b.AccID
          WHERE a.IsActive = 1
           AND b.AccActive = 1
           AND a.AccIDFrom = p_AccName
		   AND a.id<p_ID;
         SELECT IFNULL(SUM(a.debit), 0.000) INTO v_AccdebitVal FROM ExSyAccounts_AccSafeActivityTb AS a
          LEFT JOIN AccountsTb AS b ON a.AccIDFrom = b.AccID
         WHERE a.IsActive = 1
           AND b.AccActive = 1
           AND (a.CurrencyID   = p_CurrencyID OR a.CurrencyID	=13)
           AND a.AccIDFrom = p_AccName
		   AND a.id<p_ID;


		   SELECT IFNULL(SUM(a.Credit), 0.000) INTO v_CurrenCredit FROM ExSyAccounts_AccSafeActivityTb AS a
          LEFT JOIN AccountsTb AS b ON a.AccIDFrom = b.AccID
          WHERE a.IsActive = 1
           AND b.AccActive = 1
           AND a.AccIDFrom = p_AccName
		   AND a.id=p_ID;
         SELECT IFNULL(SUM(a.debit), 0.000) INTO v_CurrenDebit FROM ExSyAccounts_AccSafeActivityTb AS a
          LEFT JOIN AccountsTb AS b ON a.AccIDFrom = b.AccID
         WHERE a.IsActive = 1
           AND b.AccActive = 1
           AND a.AccIDFrom = p_AccName
		   AND a.id=p_ID;
SET v_AccVal = v_AccdebitVal - v_AccCreditVal;
		   IF v_CurrenCredit > v_CurrenDebit
		    THEN
SET v_NetVal =v_AccVal - v_CurrenCredit;
		   END IF;
		   IF v_CurrenCredit < v_CurrenDebit
		    THEN
SET v_NetVal =v_AccVal + v_CurrenDebit;
		   END IF;
		   END IF;
         RETURN v_NetVal;
     END //
DELIMITER ;

