DROP FUNCTION IF EXISTS `retenMAXtotal`;
DELIMITER //
CREATE FUNCTION `retenMAXtotal`(`p_SafeID` INT) RETURNS DOUBLE DETERMINISTIC
BEGIN
DECLARE v_AccTOTal decimal	 (13,3);
DECLARE v_maxID int;

SELECT IFNULL(max(id),0) INTO v_maxID FROM  AccEmpActivityTb WHERE SafeID=p_SafeID;

IF v_maxID> 0
 THEN
SELECT IFNULL( a.AccTOTal,0) INTO v_AccTOTal FROM AccEmpActivityTb as a where a.SafeID=p_SafeID AND a.id <=v_maxID;

END IF;
IF v_maxID= 0
 THEN
SET v_AccTOTal = 0;
END IF;

RETURN v_AccTOTal;
END //
DELIMITER ;

DROP FUNCTION IF EXISTS `Rollback_Branch_Trinsfrim_me`;
DELIMITER //
CREATE FUNCTION `Rollback_Branch_Trinsfrim_me`(`p_CurrentAccID` INT, `p_RBrType` INT, `p_RecievedCurrencyID` INT, `p_NetTotla` DECIMAL(18,3), `p_BranchRecievedID` INT) RETURNS TINYINT(1) DETERMINISTIC
BEGIN
DECLARE v_Rollback bit;
DECLARE v_CanDepit bit;
DECLARE v_IsLimted bit;
DECLARE v_LimtedVal decimal(18,3);
DECLARE v_TotalAllowedLimit decimal(18,3);

                        SELECT at.CanDebit, at.IsLimited, at.LimitedVal INTO v_CanDepit, v_IsLimted, v_LimtedVal FROM
                                AccountsTb at
                        WHERE
                                at.AccID = p_CurrentAccID;

                         IF p_RBrType=3
  THEN
                        IF IFNULL(Account_GetAccVal(p_CurrentAccID, p_RecievedCurrencyID, 0), 0) < p_NetTotla
                          AND
                          v_CanDepit = 0
                           THEN
                         set v_Rollback = 0;
                          END IF;

                        IF
                        v_CanDepit = 1
                          AND
                          v_IsLimted = 1
                          AND
                          (v_LimtedVal + IFNULL(Account_GetAccVal(p_CurrentAccID, p_RecievedCurrencyID, 0), 0)) < p_NetTotla
                           THEN
                             set v_Rollback = 0;
                          END IF;
                      END IF;

IF p_RBrType <> 3
 THEN


    SELECT a.IsLimited, IFNULL(a.LimitedVal, 0) INTO v_IsLimted, v_LimtedVal FROM
        AccountsTb a
    WHERE
        a.AccID = p_CurrentAccID;


    IF v_IsLimted = 1
     THEN

        SET v_TotalAllowedLimit = IFNULL(v_LimtedVal + Branch_GetAccVal(p_BranchRecievedID), 0);
        IF p_NetTotla > v_TotalAllowedLimit
         THEN
          set v_Rollback = 0;
        END IF;
    END IF;


                      END IF;
return IFNULL(v_Rollback,1);

                      END //
DELIMITER ;

DROP FUNCTION IF EXISTS `SafeAcc_GetAccVal`;
DELIMITER //
CREATE FUNCTION `SafeAcc_GetAccVal`(`p_AccName` BIGINT, `p_BranchID` INT, `p_CurrencyId` INT) RETURNS DECIMAL(15,3) DETERMINISTIC
BEGIN
DECLARE v_AccCreditVal decimal(15,3);
DECLARE v_AccdebitVal decimal(15,3);
DECLARE v_AccVal decimal(15,3);
DECLARE v_IsDefault bit;


	SELECT a.IsDefault INTO v_IsDefault FROM CurrencyMainTb as a where a.id=p_CurrencyId
 ORDER BY a.ID DESC LIMIT 1;


	if v_IsDefault=1
	 THEN
	SELECT IFNULL( sum(a.Credit),0.000) INTO v_AccCreditVal FROM ExSyAccounts_AccSafeActivityTb as a LEFT JOIN  AccountsTb as b on a.AccIDFrom  = b.accid WHERE b.AccID=p_AccName AND a.AccBranchID	=p_BranchID;
	SELECT IFNULL(sum(a.debit),0.000) INTO v_AccdebitVal FROM ExSyAccounts_AccSafeActivityTb as a LEFT JOIN  AccountsTb as b on a.AccIDFrom = b.accid WHERE b.AccID=p_AccName	AND a.AccBranchID	=p_BranchID;
SET v_AccVal =  v_AccdebitVal - v_AccCreditVal;
	END IF;


	if v_IsDefault=0
	 THEN
	SELECT IFNULL( sum(a.Credit),0.000) INTO v_AccCreditVal FROM ExSyAccountsCurrency_AccSafeActivityTb as a LEFT JOIN  AccountsTb as b on a.AccIDFrom  = b.accid WHERE b.AccID=p_AccName AND a.AccBranchID	=p_BranchID	AND (a.CurrencyID=p_CurrencyId or p_CurrencyId=13);
	SELECT IFNULL(sum(a.debit),0.000) INTO v_AccdebitVal FROM ExSyAccountsCurrency_AccSafeActivityTb as a LEFT JOIN  AccountsTb as b on a.AccIDFrom = b.accid WHERE b.AccID=p_AccName	AND a.AccBranchID	=p_BranchID  AND (a.CurrencyID=p_CurrencyId or p_CurrencyId=13);
SET v_AccVal =  v_AccCreditVal - v_AccdebitVal;
	END IF;






	RETURN v_AccVal;
END //
DELIMITER ;

DROP FUNCTION IF EXISTS `SafeIDBank_GetNetTotal`;
DELIMITER //
CREATE FUNCTION `SafeIDBank_GetNetTotal`(`p_AccName` BIGINT, `p_BranchID` INT, `p_CurrencyID` INT, `p_ID` BIGINT) RETURNS DECIMAL(15,3) DETERMINISTIC
BEGIN
DECLARE v_AccCreditVal DECIMAL(15, 3);
DECLARE v_AccdebitVal DECIMAL(15, 3);
DECLARE v_FinalAccVal DECIMAL(15, 3);
DECLARE v_NetVal DECIMAL(15, 3);
DECLARE v_AccVal DECIMAL(15, 3);
DECLARE v_MaxID bigint;
DECLARE v_CurrenDebit DECIMAL(15, 3);
DECLARE v_CurrenCredit DECIMAL(15, 3);
		 if p_CurrencyID = 1 or p_CurrencyID = 13
		  THEN
		 SELECT IFNULL(SUM(a.Credit), 0.000) INTO v_AccCreditVal FROM ExSyAccounts_AccSafeActivityTb AS a
          WHERE a.IsActive = 1
           AND (a.CurrencyID   = p_CurrencyID OR a.CurrencyID	=13)
           AND a.SafeID = p_AccName
           AND a.AccBranchID = p_BranchID
		   AND (a.TypeID between 15 and 18)
		   AND a.id<p_ID;
         SELECT IFNULL(SUM(a.debit), 0.000) INTO v_AccdebitVal FROM ExSyAccounts_AccSafeActivityTb AS a
         WHERE a.IsActive = 1
           AND (a.CurrencyID   = p_CurrencyID OR a.CurrencyID	=13)
           AND a.SafeID = p_AccName
           AND a.AccBranchID = p_BranchID
		   AND (a.TypeID between 15 and 18)
		   AND a.id<p_ID;


		   SELECT IFNULL(a.Credit, 0.000) INTO v_CurrenCredit FROM ExSyAccounts_AccSafeActivityTb AS a
          WHERE a.IsActive = 1
           AND (a.CurrencyID   = p_CurrencyID OR a.CurrencyID	=13)
           AND a.SafeID = p_AccName
           AND a.AccBranchID = p_BranchID
		   AND (a.TypeID between 15 and 18)
		   AND a.id=p_ID;
         SELECT IFNULL(a.debit, 0.000) INTO v_CurrenDebit FROM ExSyAccounts_AccSafeActivityTb AS a
         WHERE a.IsActive = 1
           AND (a.CurrencyID   = p_CurrencyID OR a.CurrencyID	=13)
           AND a.SafeID = p_AccName
           AND a.AccBranchID = p_BranchID
		   AND (a.TypeID between 15 and 18)
		   AND a.id=p_ID;
SET v_AccVal =  v_AccCreditVal-v_AccdebitVal;
		   IF v_CurrenCredit > v_CurrenDebit
		    THEN
SET v_NetVal =v_CurrenCredit+IFNULL(v_AccVal,0.000);
		   END IF;
		   IF v_CurrenCredit < v_CurrenDebit
		    THEN
SET v_NetVal =IFNULL(v_AccVal,0.000) - v_CurrenDebit;
		   END IF;
		   END IF;




		    if p_CurrencyID <> 1
		  THEN
		 SELECT IFNULL(SUM(a.debit), 0.000) INTO v_AccCreditVal FROM ExSyAccountsCurrency_AccSafeActivityTb AS a
          WHERE a.IsActive = 1
           AND (a.CurrencyID   = p_CurrencyID )
           AND a.SafeID = p_AccName
           AND a.AccBranchID = p_BranchID
		   AND a.id<p_ID;
         SELECT IFNULL(SUM(a.Credit), 0.000) INTO v_AccdebitVal FROM ExSyAccountsCurrency_AccSafeActivityTb AS a
         WHERE a.IsActive = 1
           AND (a.CurrencyID   = p_CurrencyID )
           AND a.SafeID = p_AccName
           AND a.AccBranchID = p_BranchID
		   AND a.id<p_ID;


		   SELECT IFNULL(a.debit, 0.000) INTO v_CurrenCredit FROM ExSyAccountsCurrency_AccSafeActivityTb AS a
          WHERE a.IsActive = 1
           AND (a.CurrencyID   = p_CurrencyID)
           AND a.SafeID = p_AccName
           AND a.AccBranchID = p_BranchID
		   AND a.id=p_ID;
         SELECT IFNULL(a.Credit, 0.000) INTO v_CurrenDebit FROM ExSyAccountsCurrency_AccSafeActivityTb AS a
         WHERE a.IsActive = 1
           AND (a.CurrencyID   = p_CurrencyID)
           AND a.SafeID = p_AccName
           AND a.AccBranchID = p_BranchID
		   AND a.id=p_ID;
SET v_AccVal = v_AccdebitVal - v_AccCreditVal;
		   IF v_CurrenCredit > v_CurrenDebit
		    THEN
SET v_NetVal =IFNULL(v_AccVal,0.000) - v_CurrenCredit;
		   END IF;
		   IF v_CurrenCredit < v_CurrenDebit
		    THEN
SET v_NetVal =IFNULL(v_AccVal,0.000) + v_CurrenDebit;
		   END IF;
		   END IF;




















         RETURN v_NetVal;
     END //
DELIMITER ;

DROP FUNCTION IF EXISTS `SafeIDBankServices_GetNetTotal`;
DELIMITER //
CREATE FUNCTION `SafeIDBankServices_GetNetTotal`(`p_AccName` BIGINT, `p_BankService` INT, `p_CurrencyID` INT, `p_ID` BIGINT) RETURNS DECIMAL(15,3) DETERMINISTIC
BEGIN
DECLARE v_AccCreditVal DECIMAL(15, 3);
DECLARE v_AccdebitVal DECIMAL(15, 3);
DECLARE v_FinalAccVal DECIMAL(15, 3);
DECLARE v_NetVal DECIMAL(15, 3);
DECLARE v_AccVal DECIMAL(15, 3);
DECLARE v_MaxID BIGINT;
DECLARE v_CurrenDebit DECIMAL(15, 3);
DECLARE v_CurrenCredit DECIMAL(15, 3);
    IF p_CurrencyID = 1
      OR
      p_CurrencyID = 13
       THEN
        SELECT IFNULL(SUM(a.Credit), 0.000) INTO v_AccCreditVal FROM
                ExSyAccounts_AccSafeActivityTb AS a
            JOIN
              BBranchTb AS b
                ON a.AccIDFrom = b.AccID
            JOIN
              bankServicesTB AS c
                ON c.BBranchID = b.id
            LEFT JOIN
              InternalEx ie
                ON a.ISID = ie.Code
                  AND c.ID = ie.ServiceType
            LEFT JOIN
              ExternalEx ee
                ON a.ISID = ee.Code
                  AND c.ID = ee.BankServiceType
        WHERE
                a.IsActive = 1
                AND (   a.CurrencyID = p_CurrencyID
                        OR a.CurrencyID = 13)
                AND a.SafeID = p_AccName
                AND c.ID = p_BankService
                AND (   ie.ServiceType = p_BankService
                        OR ee.BankServiceType = p_BankService)
                AND a.id < p_ID;
        SELECT IFNULL(SUM(a.Debit), 0.000) INTO v_AccdebitVal FROM
                ExSyAccounts_AccSafeActivityTb AS a
            JOIN
              BBranchTb AS b
                ON a.AccIDFrom = b.AccID
            JOIN
              bankServicesTB AS c
                ON c.BBranchID = b.id
            LEFT JOIN
              InternalEx ie
                ON a.ISID = ie.Code
                  AND c.ID = ie.ServiceType
            LEFT JOIN
              ExternalEx ee
                ON a.ISID = ee.Code
                  AND c.ID = ee.BankServiceType
        WHERE
                a.IsActive = 1
                AND (   a.CurrencyID = p_CurrencyID
                        OR a.CurrencyID = 13)
                AND a.SafeID = p_AccName
                AND c.ID = p_BankService
                AND (   ie.ServiceType = p_BankService
                        OR ee.BankServiceType = p_BankService)
                AND a.id < p_ID;


        SELECT IFNULL(a.Credit, 0.000) INTO v_CurrenCredit FROM
                ExSyAccounts_AccSafeActivityTb AS a
            JOIN
              BBranchTb AS b
                ON a.AccIDFrom = b.AccID
            JOIN
              bankServicesTB AS c
                ON c.BBranchID = b.id
            LEFT JOIN
              InternalEx ie
                ON a.ISID = ie.Code
                  AND c.ID = ie.ServiceType
            LEFT JOIN
              ExternalEx ee
                ON a.ISID = ee.Code
                  AND c.ID = ee.BankServiceType
        WHERE
                a.IsActive = 1
                AND (   a.CurrencyID = p_CurrencyID
                        OR a.CurrencyID = 13)
                AND a.SafeID = p_AccName
                AND c.ID = p_BankService
                AND (   ie.ServiceType = p_BankService
                        OR ee.BankServiceType = p_BankService)
                AND a.id = p_ID;
        SELECT IFNULL(a.Debit, 0.000) INTO v_CurrenDebit FROM
                ExSyAccounts_AccSafeActivityTb AS a
            JOIN
              BBranchTb AS b
                ON a.AccIDFrom = b.AccID
            JOIN
              bankServicesTB AS c
                ON c.BBranchID = b.id
            LEFT JOIN
              InternalEx ie
                ON a.ISID = ie.Code
                  AND c.ID = ie.ServiceType
            LEFT JOIN
              ExternalEx ee
                ON a.ISID = ee.Code
                  AND c.ID = ee.BankServiceType
        WHERE
                a.IsActive = 1
                AND (   a.CurrencyID = p_CurrencyID
                        OR a.CurrencyID = 13)
                AND a.SafeID = p_AccName
                AND c.ID = p_BankService
                AND (   ie.ServiceType = p_BankService
                        OR ee.BankServiceType = p_BankService)
                AND a.id = p_ID;
SET v_AccVal = v_AccCreditVal - v_AccdebitVal;
        IF v_CurrenCredit > v_CurrenDebit
           THEN
SET v_NetVal = v_CurrenCredit + IFNULL(v_AccVal, 0.000);
          END IF;
        IF v_CurrenCredit < v_CurrenDebit
           THEN
SET v_NetVal = IFNULL(v_AccVal, 0.000) - v_CurrenDebit;
          END IF;
      END IF;




    IF p_CurrencyID <> 1
       THEN
        SELECT IFNULL(SUM(a.Debit), 0.000) INTO v_AccCreditVal FROM
                ExSyAccountsCurrency_AccSafeActivityTb AS a
            JOIN
              BBranchTb AS b
                ON a.AccIDFrom = b.AccID
            JOIN
              bankServicesTB AS c
                ON c.BBranchID = b.id
        WHERE
                a.IsActive = 1
                AND (a.CurrencyID = p_CurrencyID)
                AND a.SafeID = p_AccName
                AND c.ID = p_BankService
                AND a.id < p_ID;
        SELECT IFNULL(SUM(a.Credit), 0.000) INTO v_AccdebitVal FROM
                ExSyAccountsCurrency_AccSafeActivityTb AS a
            JOIN
              BBranchTb AS b
                ON a.AccIDFrom = b.AccID
            JOIN
              bankServicesTB AS c
                ON c.BBranchID = b.id
        WHERE
                a.IsActive = 1
                AND (a.CurrencyID = p_CurrencyID)
                AND a.SafeID = p_AccName
                AND c.ID = p_BankService
                AND a.id < p_ID;


        SELECT IFNULL(a.Debit, 0.000) INTO v_CurrenCredit FROM
                ExSyAccountsCurrency_AccSafeActivityTb AS a
            JOIN
              BBranchTb AS b
                ON a.AccIDFrom = b.AccID
            JOIN
              bankServicesTB AS c
                ON c.BBranchID = b.id
        WHERE
                a.IsActive = 1
                AND (a.CurrencyID = p_CurrencyID)
                AND a.SafeID = p_AccName
                AND c.ID = p_BankService
                AND a.id = p_ID;
        SELECT IFNULL(a.Credit, 0.000) INTO v_CurrenDebit FROM
                ExSyAccountsCurrency_AccSafeActivityTb AS a
            JOIN
              BBranchTb AS b
                ON a.AccIDFrom = b.AccID
            JOIN
              bankServicesTB AS c
                ON c.BBranchID = b.id
        WHERE
                a.IsActive = 1
                AND (a.CurrencyID = p_CurrencyID)
                AND a.SafeID = p_AccName
                AND c.ID = p_BankService
                AND a.id = p_ID;
SET v_AccVal = v_AccdebitVal - v_AccCreditVal;
        IF v_CurrenCredit > v_CurrenDebit
           THEN
SET v_NetVal = IFNULL(v_AccVal, 0.000) - v_CurrenCredit;
          END IF;
        IF v_CurrenCredit < v_CurrenDebit
           THEN
SET v_NetVal = IFNULL(v_AccVal, 0.000) + v_CurrenDebit;
          END IF;
      END IF;




















    RETURN v_NetVal;
  END //
DELIMITER ;

DROP FUNCTION IF EXISTS `SafeIDCur_GetNetTotal`;
DELIMITER //
CREATE FUNCTION `SafeIDCur_GetNetTotal`(`p_BranchID` INT, `p_CurrencyID` INT, `p_ID` BIGINT) RETURNS DECIMAL(15,3) DETERMINISTIC
BEGIN
DECLARE v_AccCreditVal DECIMAL(15, 3);
DECLARE v_AccdebitVal DECIMAL(15, 3);
DECLARE v_FinalAccVal DECIMAL(15, 3);
DECLARE v_NetVal DECIMAL(15, 3);
DECLARE v_AccVal DECIMAL(15, 3);
DECLARE v_MaxID BIGINT;
DECLARE v_CurrenDebit DECIMAL(15, 3);
DECLARE v_CurrenCredit DECIMAL(15, 3);
		IF p_CurrencyID = 1
			OR
			p_CurrencyID = 13
			 THEN
				SELECT IFNULL(SUM(a.Credit), 0.000) INTO v_AccCreditVal FROM
						ExSyAccounts_AccSafeActivityTb AS a
				WHERE
						a.IsActive = 1
						AND (   a.CurrencyID = p_CurrencyID
								OR a.CurrencyID = 13)

						AND a.AccBranchID = p_BranchID
						AND a.ID < p_ID;
				SELECT IFNULL(SUM(a.Debit), 0.000) INTO v_AccdebitVal FROM
						ExSyAccounts_AccSafeActivityTb AS a
				WHERE
						a.IsActive = 1
						AND (   a.CurrencyID = p_CurrencyID
								OR a.CurrencyID = 13)

						AND a.AccBranchID = p_BranchID
						AND a.ID < p_ID;


				SELECT IFNULL(a.Credit, 0.000) INTO v_CurrenCredit FROM
						ExSyAccounts_AccSafeActivityTb AS a
				WHERE
						a.IsActive = 1
						AND (   a.CurrencyID = p_CurrencyID
								OR a.CurrencyID = 13)

						AND a.AccBranchID = p_BranchID
						AND a.ID = p_ID;
				SELECT IFNULL(a.Debit, 0.000) INTO v_CurrenDebit FROM
						ExSyAccounts_AccSafeActivityTb AS a
				WHERE
						a.IsActive = 1
						AND (   a.CurrencyID = p_CurrencyID
								OR a.CurrencyID = 13)

						AND a.AccBranchID = p_BranchID
						AND a.ID = p_ID;
SET v_AccVal = v_AccdebitVal - v_AccCreditVal;
				IF v_CurrenCredit > v_CurrenDebit
					 THEN
SET v_NetVal = IFNULL(v_AccVal, 0.000) - v_CurrenCredit;
					END IF;
				IF v_CurrenCredit < v_CurrenDebit
					 THEN
SET v_NetVal = IFNULL(v_AccVal, 0.000) + v_CurrenDebit;
					END IF;
			END IF;




		IF p_CurrencyID <> 1
			 THEN
				SELECT IFNULL(SUM(a.ACC_DEPET_TO), 0.000) INTO v_AccCreditVal FROM
						ExSyAccountsCurrency_CurrencymovementPruse AS a
				WHERE
						a.IsActive = 1
						AND (a.AccFrom = p_CurrencyID)

						AND a.BID = p_BranchID
						AND a.ID < p_ID;
				SELECT IFNULL(SUM(a.CRedetTO), 0.000) INTO v_AccdebitVal FROM
						ExSyAccountsCurrency_CurrencymovementPruse AS a
				WHERE
						a.IsActive = 1
						AND (a.AccFrom = p_CurrencyID)

						AND a.BID = p_BranchID
						AND a.ID < p_ID;


				SELECT IFNULL(a.ACC_DEPET_TO, 0.000) INTO v_CurrenCredit FROM
						ExSyAccountsCurrency_CurrencymovementPruse AS a
				WHERE
						a.IsActive = 1
						AND (a.AccFrom = p_CurrencyID)

						AND a.BID = p_BranchID
						AND a.ID = p_ID;
				SELECT IFNULL(a.CRedetTO, 0.000) INTO v_CurrenDebit FROM
						ExSyAccountsCurrency_CurrencymovementPruse AS a
				WHERE
						a.IsActive = 1
						AND (a.AccFrom = p_CurrencyID)

						AND a.BID = p_BranchID
						AND a.ID = p_ID;
SET v_AccVal = v_AccdebitVal - v_AccCreditVal;
				IF v_CurrenCredit > v_CurrenDebit
					 THEN
SET v_NetVal = IFNULL(v_AccVal, 0.000) - v_CurrenCredit;
					END IF;
				IF v_CurrenCredit < v_CurrenDebit
					 THEN
SET v_NetVal = IFNULL(v_AccVal, 0.000) + v_CurrenDebit;
					END IF;
			END IF;




















		RETURN v_NetVal;
	END //
DELIMITER ;

