DROP FUNCTION IF EXISTS `Sum_MainSAfes`;
DELIMITER //
CREATE FUNCTION `Sum_MainSAfes`(`p_AccBranchID` INT, `p_CurrencyID` INT, `p_SafeType` INT) RETURNS DOUBLE DETERMINISTIC
BEGIN
DECLARE v_sumcredet FLOAT DEFAULT 0;
DECLARE v_IsDefault BIT;


    SELECT IsDefault INTO v_IsDefault FROM
            CurrencyMainTb
    WHERE
            id = p_CurrencyID
 ORDER BY CurrencyMainTb.ID DESC LIMIT 1;


    IF v_IsDefault = 1
       THEN
        SELECT IFNULL(SUM(A.Credit), 0) - IFNULL(SUM(A.Debit), 0) INTO v_sumcredet FROM
                ExSyAccounts_AccSafeActivityTb AS A
            JOIN
              AccountsTb AS B
                ON A.AccIDFrom = B.AccID
        WHERE
                A.IsActive = 1
                AND A.AccBranchID = p_AccBranchID
                AND B.AccParent = 1010101
                AND A.CurrencyID = p_CurrencyID;
       ELSE

        IF p_SafeType = 1
           THEN
            SELECT IFNULL(SUM(A.Debit), 0) - IFNULL(SUM(A.Credit), 0) INTO v_sumcredet FROM
                    ExSyAccountsCurrency_AccSafeActivityTb AS A
                JOIN
                  AccountsTb AS B
                    ON A.AccIDFrom = B.AccID
            WHERE
                    A.IsActive = 1
                    AND A.AccBranchID = p_AccBranchID
                    AND LEFT(B.AccParent, 5) = 10102
                    AND A.CurrencyID = p_CurrencyID;
           ELSEIF  p_SafeType = 2
           THEN
            SELECT IFNULL(SUM(A.Credit), 0) - IFNULL(SUM(A.Debit), 0) INTO v_sumcredet FROM
                    ExSyAccountsCurrency_AccSafeActivityTb AS A
                JOIN
                  AccountsTb AS B
                    ON A.AccIDFrom = B.AccID
            WHERE
                    A.IsActive = 1
                    AND A.AccBranchID = p_AccBranchID
                    AND LEFT(B.AccParent, 5) = 10104
                    AND A.CurrencyID = p_CurrencyID;
           ELSEIF  p_SafeType = 3
           THEN

            SELECT IFNULL(SUM(A.Credit), 0) - IFNULL(SUM(A.Debit), 0) INTO v_sumcredet FROM
                    ExSyAccountsCurrency_AccSafeActivityTb AS A
                JOIN
                  AccountsTb AS B
                    ON A.AccIDFrom = B.AccID
            WHERE
                    A.IsActive = 1
                    AND A.AccBranchID = p_AccBranchID
                    AND LEFT(B.AccParent, 5) = 10105
                    AND A.CurrencyID = p_CurrencyID;
          END IF;
      END IF;

    RETURN IFNULL(v_sumcredet, 0);
  END //
DELIMITER ;

DROP FUNCTION IF EXISTS `sumcredet`;
DELIMITER //
CREATE FUNCTION `sumcredet`(`p_tybid` INT, `p_acccode` BIGINT, `p_date1` DATE, `p_date2` DATE, `p_CurrencyFrom` INT) RETURNS DOUBLE DETERMINISTIC
BEGIN
DECLARE v_sumcredet FLOAT;
DECLARE v_CRUNSEFROM BIT;
		SELECT IsDefault INTO v_CRUNSEFROM FROM
				CurrencyMainTb AS CMT
		WHERE
				id = p_CurrencyFrom
 ORDER BY CMT.ID DESC LIMIT 1;
		IF v_CRUNSEFROM = 1
			 THEN
				SELECT IFNULL(SUM(Credit), 0) INTO v_sumcredet FROM
						ExSyAccounts_AccSafeActivityTb AS a
					INNER JOIN
						AccountsTb AS b
							ON b.AccID = a.AccIDFrom
				WHERE
						b.AccCode = p_acccode
						AND a.InsertDate BETWEEN CAST(p_date1 AS DATE) AND CAST(p_date2 AS DATE)
						AND a.IsActive = 1
						AND (a.CurrencyID=p_CurrencyFrom or a.CurrencyID=13);
			END IF;

		IF v_CRUNSEFROM = 0
			 THEN
				SELECT IFNULL(SUM(Credit), 0) INTO v_sumcredet FROM
						ExSyAccountsCurrency_AccSafeActivityTb AS a
					INNER JOIN
						AccountsTb AS b
							ON b.AccID = a.AccIDFrom
				WHERE
						b.AccCode = p_acccode
						AND a.InsertDate BETWEEN CAST(p_date1 AS DATE) AND CAST(p_date2 AS DATE)
						AND a.IsActive = 1
						AND a.CurrencyID = p_CurrencyFrom;
			END IF;


		RETURN v_sumcredet;
	END //
DELIMITER ;

DROP FUNCTION IF EXISTS `sumcredet1`;
DELIMITER //
CREATE FUNCTION `sumcredet1`(`p_tybid` INT, `p_acccode` BIGINT, `p_date1` DATE, `p_date2` DATE, `p_CurrencyFrom` INT, `p_BranchID` INT) RETURNS DOUBLE DETERMINISTIC
BEGIN
DECLARE v_sumcredet FLOAT;
DECLARE v_CRUNSEFROM BIT;
DECLARE v_MainBranch INT;
DECLARE v_Ismain bit;

		SELECT co.ismain INTO v_Ismain FROM CoBranch as co where co.ID=p_BranchID;
			SELECT co.id INTO v_MainBranch FROM CoBranch as co where co.ismain=1;
		SELECT IsDefault INTO v_CRUNSEFROM FROM
				CurrencyMainTb AS CMT
		WHERE
				id = p_CurrencyFrom
 ORDER BY CMT.ID DESC LIMIT 1;
		IF v_CRUNSEFROM = 1
			 THEN
			if v_Ismain=1
			 THEN
				SELECT IFNULL(SUM(Credit), 0) INTO v_sumcredet FROM
						ExSyAccounts_AccSafeActivityTb AS a
					INNER JOIN
						AccountsTb AS b
							ON b.AccID = a.AccIDFrom
				WHERE
						b.AccCode = p_acccode
						AND a.InsertDate BETWEEN CAST(p_date1 AS DATE) AND CAST(p_date2 AS DATE)
						AND a.IsActive = 1
						AND (a.CurrencyID=p_CurrencyFrom or a.CurrencyID=13)
						AND a.AccBranchID=v_MainBranch;
			END IF;

			if v_Ismain<>1
			 THEN
				SELECT IFNULL(SUM(Credit), 0) INTO v_sumcredet FROM
						ExSyAccounts_AccSafeActivityTb AS a
					INNER JOIN
						AccountsTb AS b
							ON b.AccID = a.AccIDFrom
				WHERE
						b.AccCode = p_acccode
						AND a.InsertDate BETWEEN CAST(p_date1 AS DATE) AND CAST(p_date2 AS DATE)
						AND a.IsActive = 1
						AND (a.CurrencyID=p_CurrencyFrom or a.CurrencyID=13)
						AND a.AccBranchID=p_BranchID;
			END IF;

					END IF;
		IF v_CRUNSEFROM = 0
			 THEN
				SELECT IFNULL(SUM(Credit), 0) INTO v_sumcredet FROM
						ExSyAccountsCurrency_AccSafeActivityTb AS a
					INNER JOIN
						AccountsTb AS b
							ON b.AccID = a.AccIDFrom
				WHERE
						b.AccCode = p_acccode
						AND a.InsertDate BETWEEN CAST(p_date1 AS DATE) AND CAST(p_date2 AS DATE)
						AND a.IsActive = 1
						AND a.CurrencyID = p_CurrencyFrom;
			END IF;


		RETURN v_sumcredet;
	END //
DELIMITER ;

DROP FUNCTION IF EXISTS `sumDEBETalter`;
DELIMITER //
CREATE FUNCTION `sumDEBETalter`(`p_tybid` INT, `p_acccode` BIGINT, `p_date1` DATE, `p_date2` DATE, `p_CurrencyFrom` INT) RETURNS DOUBLE DETERMINISTIC
BEGIN
DECLARE v_debit FLOAT;
DECLARE v_CurrencyID BIT;
		SELECT IsDefault INTO v_CurrencyID FROM
				CurrencyMainTb AS CMT WHERE CMT.ID=p_CurrencyFrom
 ORDER BY CMT.ID DESC LIMIT 1;
		IF v_CurrencyID = 1
			 THEN
				IF p_tybid = 0
					 THEN
						SELECT IFNULL(SUM(Debit), 0) INTO v_debit FROM
								ExSyAccounts_AccSafeActivityTb AS a
							INNER JOIN
								AccountsTb AS b
									ON b.AccID = a.AccIDFrom
						WHERE
								b.AccParent = p_acccode
								AND a.InsertDate BETWEEN CAST(p_date1 AS DATE) AND CAST(p_date2 AS DATE)
								AND b.AccActive = 1
								AND a.IsActive = 1
								AND (a.CurrencyID=p_CurrencyFrom or a.CurrencyID=13);
					END IF;
				IF p_tybid = 1
					 THEN
						SELECT IFNULL(SUM(Debit), 0) INTO v_debit FROM
								ExSyAccounts_AccSafeActivityTb AS a
							INNER JOIN
								AccountsTb AS b
									ON b.AccID = a.AccIDFrom
						WHERE
								b.AccCode = p_acccode
								AND a.InsertDate BETWEEN CAST(p_date1 AS DATE) AND CAST(p_date2 AS DATE)
								AND b.AccActive = 1
								AND a.IsActive = 1
								AND (a.CurrencyID=p_CurrencyFrom or a.CurrencyID=13);
					END IF;

			END IF;
		IF v_CurrencyID =0
			 THEN
				IF p_tybid = 0
					 THEN
						SELECT IFNULL(SUM(Debit), 0) INTO v_debit FROM
								ExSyAccountsCurrency_AccSafeActivityTb AS a
							INNER JOIN
								AccountsTb AS b
									ON b.AccID = a.AccIDFrom
						WHERE
								b.AccParent = p_acccode
								AND a.InsertDate BETWEEN CAST(p_date1 AS DATE) AND CAST(p_date2 AS DATE)
								AND b.AccActive = 1
								AND a.IsActive = 1
								AND a.CurrencyID = p_CurrencyFrom;
					END IF;
				IF p_tybid = 1
					 THEN
						SELECT IFNULL(SUM(Debit), 0) INTO v_debit FROM
								ExSyAccountsCurrency_AccSafeActivityTb AS a
							INNER JOIN
								AccountsTb AS b
									ON b.AccID = a.AccIDFrom
						WHERE
								b.AccCode = p_acccode
								AND a.InsertDate BETWEEN CAST(p_date1 AS DATE) AND CAST(p_date2 AS DATE)
								AND b.AccActive = 1
								AND a.IsActive = 1
								AND a.CurrencyID = p_CurrencyFrom;
					END IF;

			END IF;


		RETURN v_debit;
	END //
DELIMITER ;

DROP FUNCTION IF EXISTS `sumDEBETalter1`;
DELIMITER //
CREATE FUNCTION `sumDEBETalter1`(`p_tybid` INT, `p_acccode` BIGINT, `p_date1` DATE, `p_date2` DATE, `p_CurrencyFrom` INT, `p_BranchID` INT) RETURNS DOUBLE DETERMINISTIC
BEGIN
DECLARE v_debit FLOAT;
DECLARE v_CurrencyID BIT;
DECLARE v_MainBranch INT;
DECLARE v_Ismain bit;
		SELECT co.ismain INTO v_Ismain FROM CoBranch as co where co.ID=p_BranchID;
			SELECT co.id INTO v_MainBranch FROM CoBranch as co where co.ismain=1;

		SELECT IsDefault INTO v_CurrencyID FROM
				CurrencyMainTb AS CMT WHERE CMT.ID=p_CurrencyFrom
 ORDER BY CMT.ID DESC LIMIT 1;
		IF v_CurrencyID = 1
			 THEN

				IF p_tybid = 0
					 THEN
						SELECT IFNULL(SUM(Debit), 0) INTO v_debit FROM
								ExSyAccounts_AccSafeActivityTb AS a
							INNER JOIN
								AccountsTb AS b
									ON b.AccID = a.AccIDFrom
						WHERE
								b.AccParent = p_acccode
								AND a.InsertDate BETWEEN CAST(p_date1 AS DATE) AND CAST(p_date2 AS DATE)

								AND a.IsActive = 1
								AND (a.CurrencyID=p_CurrencyFrom or a.CurrencyID=13);

					END IF;
				IF p_tybid = 1
					 THEN
					if v_Ismain=1
			 THEN
						SELECT IFNULL(SUM(Debit), 0) INTO v_debit FROM
								ExSyAccounts_AccSafeActivityTb AS a
							INNER JOIN
								AccountsTb AS b
									ON b.AccID = a.AccIDFrom
						WHERE
								b.AccCode = p_acccode
								AND a.InsertDate BETWEEN CAST(p_date1 AS DATE) AND CAST(p_date2 AS DATE)

								AND a.IsActive = 1
								AND (a.CurrencyID=p_CurrencyFrom or a.CurrencyID=13)
								AND a.AccBranchID=v_MainBranch;
					END IF;
					if v_Ismain<>1
			 THEN
						SELECT IFNULL(SUM(Debit), 0) INTO v_debit FROM
								ExSyAccounts_AccSafeActivityTb AS a
							INNER JOIN
								AccountsTb AS b
									ON b.AccID = a.AccIDFrom
						WHERE
								b.AccCode = p_acccode
								AND a.InsertDate BETWEEN CAST(p_date1 AS DATE) AND CAST(p_date2 AS DATE)

								AND a.IsActive = 1
								AND (a.CurrencyID=p_CurrencyFrom or a.CurrencyID=13)
								AND a.AccBranchID=p_BranchID;
					END IF;
					END IF;

			END IF;
		IF v_CurrencyID =0
			 THEN
				IF p_tybid = 0
					 THEN
						SELECT IFNULL(SUM(Debit), 0) INTO v_debit FROM
								ExSyAccountsCurrency_AccSafeActivityTb AS a
							INNER JOIN
								AccountsTb AS b
									ON b.AccID = a.AccIDFrom
						WHERE
								b.AccParent = p_acccode
								AND a.InsertDate BETWEEN CAST(p_date1 AS DATE) AND CAST(p_date2 AS DATE)

								AND a.IsActive = 1
								AND a.CurrencyID = p_CurrencyFrom;
					END IF;
				IF p_tybid = 1
					 THEN
						SELECT IFNULL(SUM(Debit), 0) INTO v_debit FROM
								ExSyAccountsCurrency_AccSafeActivityTb AS a
							INNER JOIN
								AccountsTb AS b
									ON b.AccID = a.AccIDFrom
						WHERE
								b.AccCode = p_acccode
								AND a.InsertDate BETWEEN CAST(p_date1 AS DATE) AND CAST(p_date2 AS DATE)

								AND a.IsActive = 1
								AND a.CurrencyID = p_CurrencyFrom;
					END IF;

			END IF;


		RETURN v_debit;
	END //
DELIMITER ;

DROP FUNCTION IF EXISTS `sumtotalaccounadi`;
DELIMITER //
CREATE FUNCTION `sumtotalaccounadi`(`p_accbid` INT) RETURNS DOUBLE DETERMINISTIC
BEGIN
DECLARE v_sumcredet FLOAT;
DECLARE v_sumdebet FLOAT;
DECLARE v_totatel FLOAT;

	SELECT IFNULL( SUM( a.Credit ), 0 ) INTO v_sumcredet FROM ExSyAccounts_AccSafeActivityTb AS a
INNER JOIN
AccountsTb AS b
ON b.AccID=a.AccIDFrom
   AND a.IsActive=1
	WHERE a.AccIDFrom=p_accbid;


	SELECT IFNULL( SUM( a.Debit ), 0 ) INTO v_sumdebet FROM ExSyAccounts_AccSafeActivityTb AS a
INNER JOIN
AccountsTb AS b
ON b.AccID=a.AccIDFrom
   AND IsActive=1
	WHERE a.AccIDFrom=p_accbid;
SET v_totatel=v_sumcredet-v_sumdebet;
	RETURN v_totatel;
END //
DELIMITER ;

DROP FUNCTION IF EXISTS `TestAccount_CanUseVal`;
DELIMITER //
CREATE FUNCTION `TestAccount_CanUseVal`(`p_AccID` BIGINT, `p_CurrencyID` INT, `p_IsBank` TINYINT UNSIGNED, `p_Val` DECIMAL(18,6)) RETURNS TINYINT(1) DETERMINISTIC
BEGIN
DECLARE v_CanDepit BIT;
DECLARE v_IsLimted BIT;
DECLARE v_LimtedVal DECIMAL(18, 3);
DECLARE v_AccVal DECIMAL(18, 6);

    SELECT CASE                                 WHEN at.AccDmType = 0                                   AND at.AccParent NOT LIKE '101010%'                                    AND at.AccParent NOT LIKE '101020%'                                    AND at.AccParent NOT LIKE '101070%'                                    THEN                                   1                                 ELSE                                 at.CanDebit                         END, at.IsLimited, IFNULL(at.LimitedVal, 0) INTO v_CanDepit, v_IsLimted, v_LimtedVal FROM
            AccountsTb at
    WHERE
            at.AccID = p_AccID;


    SET v_AccVal = IFNULL(Account_GetAccVal(p_AccID, p_CurrencyID, p_IsBank), 0);
    IF v_AccVal < p_Val
       THEN
        IF v_CanDepit = 0 OR p_IsBank=1
           THEN
            RETURN 0;
          END IF;

        IF v_CanDepit = 1
          AND
          v_IsLimted = 1
          AND
          (v_LimtedVal + v_AccVal) < p_Val
           THEN
            RETURN 0;
          END IF;

      END IF;


    RETURN 1;
  END //
DELIMITER ;

DROP FUNCTION IF EXISTS `TransBetweenAccountsTB_GetMaxIDCode`;
DELIMITER //
CREATE FUNCTION `TransBetweenAccountsTB_GetMaxIDCode`() RETURNS BIGINT DETERMINISTIC
BEGIN
DECLARE v_IDCode BIGINT;
		SELECT IFNULL(MAX(a.IDCode), 0) + 1 INTO v_IDCode FROM
				TransBetweenAccountsTB AS a;
		IF v_IDCode = 0
			 THEN
SET v_IDCode = 1;
			END IF;
		RETURN v_IDCode;
	END //
DELIMITER ;

DROP FUNCTION IF EXISTS `WithdrawalTb_GetMaxIDCode`;
DELIMITER //
CREATE FUNCTION `WithdrawalTb_GetMaxIDCode`() RETURNS BIGINT DETERMINISTIC
BEGIN
DECLARE v_IDCode bigint;
	SELECT IFNULL(MAx(a.WIDCode),0) + 1 INTO v_IDCode FROM WithdrawalTb AS a;
	RETURN v_IDCode;
END //
DELIMITER ;

DROP FUNCTION IF EXISTS `ZRPT_EMPORCUST_GetAccVal`;
DELIMITER //
CREATE FUNCTION `ZRPT_EMPORCUST_GetAccVal`(`p_AccName` INT, `p_BranchID` INT) RETURNS DECIMAL(15,3) DETERMINISTIC
BEGIN
DECLARE v_AccCreditVal DECIMAL(15, 3);
DECLARE v_AccdebitVal DECIMAL(15, 3);
DECLARE v_AccVal DECIMAL(15, 3);

  BEGIN
  SELECT IFNULL( SUM( a.CRedetTO ), 0.000 ) INTO v_AccCreditVal FROM ExSyAccountsCurrency_CurrencymovementPruse AS a
  WHERE AccFrom=p_AccName
        AND a.BID=p_BranchID;
  SELECT IFNULL( SUM( a.ACC_DEPET_TO ), 0.000 ) INTO v_AccdebitVal FROM ExSyAccountsCurrency_CurrencymovementPruse AS a
  WHERE AccFrom=p_AccName
        AND a.BID=p_BranchID;
SET v_AccVal=v_AccCreditVal-v_AccdebitVal;
  END;

  RETURN v_AccVal;
END //
DELIMITER ;

